const MOUSE_SENSITIVITY: f32 = 0.0022;
const TICK: Duration = Duration::from_millis(50);
/// Vanilla's `PlayerControllerMP.getBlockReachDistance`.
const REACH_CREATIVE: f64 = 5.0;
const REACH_SURVIVAL: f64 = 4.5;
/// Selection outline colour, matching vanilla's black wireframe.
const OUTLINE_COLOR: [f32; 3] = [0.0, 0.0, 0.0];
/// How long a status ping may take before the row is shown as offline.
const PING_TIMEOUT: Duration = Duration::from_secs(1);
/// Two clicks on the same server within this window join it (`double-click`).
const DOUBLE_CLICK: Duration = Duration::from_millis(400);

pub struct PlayOptions {
    /// None opens the title screen instead of connecting straight away.
    pub address: Option<ServerAddress>,
    pub username: String,
    pub assets_dir: std::path::PathBuf,
    pub fly: bool,
    /// Single-player world seed; random when absent.
    pub seed: Option<u64>,
    /// Sign in with the cached Microsoft session instead of connecting offline.
    pub online: bool,
    /// Where the cached session lives.
    pub session_path: std::path::PathBuf,
    /// Where the saved multiplayer list lives.
    pub servers_path: std::path::PathBuf,
}

enum NetMsg {
    Chunks(Vec<ChunkColumn>),
    Unload(i32, i32),
    Chat(String),
    /// The full entity table, replaced wholesale. Cheap enough at 20 Hz.
    Entities(Vec<EntitySnapshot>),
    /// The full block-entity table, replaced wholesale.
    BlockEntities(Vec<BlockEntity>),
    /// Server-triggered particle bursts.
    Particles(Vec<play::ParticleSpawn>),
    /// Server-triggered positional sounds.
    Sound(play::SoundEffect),
    /// Tab-list skin hashes (uuid, texture hash, slim model).
    Skins(Vec<([u8; 16], String, bool)>),
    /// Map pixels arrived for one map id.
    Map(i32, MapState),
    Error(String),
}

/// One finished server-list ping, sent from its worker thread.
struct PingReply {
    address: String,
    ping: Ping,
}

/// One tracked entity, copied out of the client so the render thread can
/// interpolate it without touching the network thread's state.
#[derive(Debug, Clone)]
struct EntitySnapshot {
    id: i32,
    player: bool,
    uuid: [u8; 16],
    /// Interpolation start and latest server position.
    prev: [f64; 3],
    position: [f64; 3],
    prev_yaw: f32,
    yaw: f32,
    head_yaw: f32,
    prev_head_yaw: f32,
    pitch: f32,
    /// Mob type, used to choose the model and texture.
    kind: u8,
    /// Item id and metadata for a dropped stack, `None` for players and mobs.
    item: Option<(i16, i16)>,
    name: String,
    show_name: bool,
    health: f32,
    flags: u8,
    /// Held item, taken from the equipment slot for the hand renderer.
    held_item: Option<ItemStack>,
    /// Boots, leggings, chestplate, helmet.
    armor: [Option<ItemStack>; 4],
    /// `(direction, rotation, framed item)` for an item frame.
    item_frame: Option<(u8, u8, Option<ItemStack>)>,
    velocity: [f64; 3],
    animation: u8,
    animation_ticks: u8,
}

impl EntitySnapshot {
    fn from_entity(entity: &nephele_client::Entity) -> Self {
        let (player, uuid, kind) = match &entity.kind {
            nephele_client::EntityKind::Player { uuid, .. } => (true, *uuid, 0),
            nephele_client::EntityKind::Mob { kind } => (false, [0; 16], *kind),
            nephele_client::EntityKind::Item { .. } => (false, [0; 16], 0),
            nephele_client::EntityKind::ItemFrame { .. } => (false, [0; 16], 0),
        };
        let item = match entity.kind {
            nephele_client::EntityKind::Item { id, meta } => Some((id, meta)),
            _ => None,
        };
        let item_frame = match &entity.kind {
            nephele_client::EntityKind::ItemFrame {
                direction,
                item,
                rotation,
            } => Some((*direction, *rotation, *item)),
            _ => None,
        };
        let held_item = entity.equipment[play::equipment_slot::HELD as usize];
        let armor = [
            entity.equipment[play::equipment_slot::BOOTS as usize],
            entity.equipment[play::equipment_slot::LEGGINGS as usize],
            entity.equipment[play::equipment_slot::CHESTPLATE as usize],
            entity.equipment[play::equipment_slot::HELMET as usize],
        ];
        Self {
            id: entity.id,
            player,
            uuid,
            prev: entity.prev,
            position: entity.position,
            prev_yaw: entity.prev_yaw,
            yaw: entity.yaw,
            head_yaw: entity.head_yaw,
            prev_head_yaw: entity.prev_head_yaw,
            pitch: entity.pitch,
            kind,
            item,
            name: entity.name().to_string(),
            show_name: entity.shows_name(),
            health: entity.health(),
            flags: entity.metadata.flags,
            held_item,
            armor,
            item_frame,
            velocity: entity.velocity,
            animation: entity.animation,
            animation_ticks: entity.animation_ticks,
        }
    }
}

struct Shared {
    player: PlayerState,
    yaw: f32,
    pitch: f32,
    input: Input,
    teleport: Option<[f64; 3]>,
    status: String,
    spawned: bool,
    error: Option<String>,
    /// Left mouse button held.
    attacking: bool,
    /// Right click queued; the network thread consumes and clears it.
    use_pressed: bool,
    /// Hotbar slot the player just selected.
    pending_slot: Option<i16>,
    /// Set by the death screen, drained by the network loop.
    pending_respawn: bool,
    /// Written by the network thread, read by the renderer.
    aim: Option<Aim>,
    break_stage: Option<u8>,
    held_slot: i16,
    creative: bool,
    /// Mirror of the 45-slot player container, for the hotbar.
    inventory: Vec<Option<ItemStack>>,
    health: f32,
    food: i32,
    xp_bar: f32,
    xp_level: i32,
    chunks: usize,
    /// Requested by the creative inventory, applied by the network thread.
    give_item: Option<(i16, ItemStack)>,
    /// Chat lines typed by the player; the game thread sends them on.
    chat_out: Vec<String>,
    /// `/setblock` requests, applied to the game thread's own world copy.
    world_edits: Vec<(i32, i32, i32, u16)>,
    /// `/gamemode` requests; `true` is creative.
    creative_override: Option<bool>,
    /// Container clicks from the inventory screen; the game thread sends them.
    inventory_clicks: Vec<(i16, i8, i8, Option<ItemStack>)>,
    /// Slots of the server's open container (crafting table), and whether one is.
    window_slots: Vec<Option<ItemStack>>,
    window_open: bool,
    /// Server window id, or 1 for the local crafting-table window.
    window_id: Option<u8>,
    /// Offline crafting-table grid and cursor; the player's inventory stays above.
    local_container: LocalContainer,
    /// Ask the game thread to send `C0D` for the open container.
    close_window: bool,
    /// Single-player has no server to apply clicks, so the UI applies them.
    local: bool,
    /// Render distance, pushed to the server as a client-settings update.
    view_distance: u8,
    /// World time in ticks, 0..24000. Singleplayer advances it; multiplayer
    /// copies the server's `S03 Time Update`.
    time_of_day: i64,
    /// One-shot `/time set` override, consumed by the game thread.
    time_override: Option<i64>,
    /// Position at the start of the current tick, and when that tick began, so
    /// the renderer can interpolate between 20 Hz physics ticks.
    prev_position: [f64; 3],
    tick_at: Instant,
}

fn refresh_local_crafting_preview(state: &mut Shared) {
    if !state.local {
        return;
    }
    if state.window_id == Some(1) {
        sync_local_table_inventory(state);
    } else {
        let result = inventory::player_crafting_result(&state.inventory);
        if let Some(slot) = state.inventory.first_mut() {
            *slot = result;
        }
    }
}

fn sync_local_table_inventory(state: &mut Shared) {
    if state.window_id != Some(1) || state.window_slots.len() < 46 {
        return;
    }
    state.window_slots[1..10].copy_from_slice(state.local_container.grid());
    state.window_slots[0] = inventory::table_crafting_result(&state.window_slots);
    state.window_slots[10..46].copy_from_slice(&state.inventory[9..45]);
}

fn open_local_crafting_table(state: &mut Shared) {
    state.local_container = LocalContainer::default();
    state.window_slots = vec![None; 46];
    state.window_id = Some(1);
    state.window_open = true;
    sync_local_table_inventory(state);
}

fn insert_player_stack(slots: &mut [Option<ItemStack>], item: ItemStack) -> Option<ItemStack> {
    let item = inventory::insert_stack(&mut slots[36..45], item)?;
    inventory::insert_stack(&mut slots[9..36], item)
}

fn local_block_drop(block: BlockState) -> Option<ItemStack> {
    let (id, meta) = match block.id() {
        0 | 7 | 8..=11 | 18 | 51 | 90 => return None,
        1 => (4, 0),                  // Stone drops cobblestone.
        2 => (3, 0),                  // Grass blocks drop dirt.
        17 => (17, block.meta() & 3), // The log axis is not item metadata.
        id => (id, block.meta()),
    };
    Some(ItemStack::new(id as i16, 1, meta as i16))
}

fn add_local_item(state: &mut Shared, item: ItemStack) {
    let Some(item) = inventory::insert_stack(&mut state.inventory[36..45], item) else {
        return;
    };
    let _ = inventory::insert_stack(&mut state.inventory[9..36], item);
}

fn consume_held_block(state: &mut Shared, slot: usize, block_state: u16) {
    let Some(item) = state.inventory.get_mut(slot).and_then(Option::as_mut) else {
        return;
    };
    if item.block_state() != Some(block_state) {
        return;
    }
    item.count -= 1;
    let empty = item.count <= 0;
    if empty {
        state.inventory[slot] = None;
    }
}

fn take_local_crafting_output(state: &mut Shared, cursor: &mut Option<ItemStack>) {
    let result = inventory::player_crafting_result(&state.inventory);
    let Some(result) = result else {
        return;
    };
    if !inventory::take_crafting_result(cursor, result) {
        return;
    }

    inventory::consume_crafting_grid(&mut state.inventory[1..5]);
    refresh_local_crafting_preview(state);
}

fn shift_craft_local_outputs(state: &mut Shared) {
    if state.window_id == Some(1) {
        for _ in 0..64 {
            let mut container = state.local_container.clone();
            let Some(result) = container.click(0, 0, true) else {
                break;
            };

            let mut inventory = state.inventory.clone();
            if insert_player_stack(&mut inventory, result).is_some() {
                break;
            }
            state.local_container = container;
            state.inventory = inventory;
        }
        refresh_local_crafting_preview(state);
        return;
    }

    for _ in 0..64 {
        let result = inventory::player_crafting_result(&state.inventory);
        let Some(result) = result else {
            break;
        };

        let mut inventory = state.inventory.clone();
        if insert_player_stack(&mut inventory, result).is_some() {
            break;
        }
        state.inventory = inventory;
        inventory::consume_crafting_grid(&mut state.inventory[1..5]);
    }
    refresh_local_crafting_preview(state);
}

pub fn run(options: PlayOptions) -> Result<(), Box<dyn Error>> {
    perf::start();
    let settings = initial_settings();
    let shared = Arc::new(Mutex::new(Shared {
        player: PlayerState::default(),
        yaw: 0.0,
        pitch: 0.0,
        input: Input::default(),
        teleport: None,
        status: String::new(),
        spawned: false,
        error: None,
        attacking: false,
        use_pressed: false,
        pending_slot: None,
        pending_respawn: false,
        aim: None,
        break_stage: None,
        held_slot: 0,
        creative: false,
        inventory: vec![None; 45],
        health: 20.0,
        food: 20,
        xp_bar: 0.0,
        xp_level: 0,
        chunks: 0,
        give_item: None,
        chat_out: Vec::new(),
        world_edits: Vec::new(),
        creative_override: None,
        inventory_clicks: Vec::new(),
        window_slots: Vec::new(),
        window_open: false,
        window_id: None,
        local_container: LocalContainer::default(),
        close_window: false,
        local: false,
        view_distance: configured_view_distance(&settings),
        time_of_day: 6000,
        time_override: None,
        prev_position: [0.5, 80.0, 0.5],
        tick_at: Instant::now(),
    }));

    let (tx, rx) = mpsc::channel::<NetMsg>();

    let event_loop = EventLoop::new()?;
    event_loop.set_control_flow(ControlFlow::Poll);
    let mut app = LiveApp::new(options, shared, rx, tx, settings);
    event_loop.run_app(&mut app)?;
    match app.error.take() {
        Some(err) => Err(err),
        None => Ok(()),
    }
}

/// One 20 Hz simulation step, shared by the network and single-player loops.
fn step_player(shared: &Arc<Mutex<Shared>>, world: &World) -> (Vec3, f32, f32, bool) {
    let mut state = shared.lock().unwrap();
    if let Some([x, y, z]) = state.teleport.take() {
        state.player.teleport(x, y, z);
    }
    state.prev_position = [state.player.x, state.player.y, state.player.z];
    let input = state.input;
    let yaw = state.yaw;
    state.player.step(TICK.as_secs_f64(), &input, yaw, world);
    state.tick_at = Instant::now();
    (
        Vec3::new(state.player.x, state.player.y, state.player.z),
        state.yaw,
        state.pitch,
        state.player.on_ground,
    )
}

fn fresh_world_seed() -> u64 {
    let time = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|elapsed| elapsed.as_nanos() as u64)
        .unwrap_or(1);
    time ^ (u64::from(std::process::id()) << 32)
}

/// One simulated single-player mob. The network path receives the same model
/// data as packets; this is the local stand-in for a server's mob AI.
struct LocalMob {
    id: i32,
    kind: u8,
    position: [f64; 3],
    prev: [f64; 3],
    yaw: f32,
    prev_yaw: f32,
    head_yaw: f32,
    prev_head_yaw: f32,
    health: f32,
    velocity: [f64; 3],
    sound_timer: f32,
    wander: f32,
}

impl LocalMob {
    fn new(id: i32, kind: u8, position: [f64; 3]) -> Self {
        let yaw = 0.0;
        Self {
            id,
            kind,
            position,
            prev: position,
            yaw,
            prev_yaw: yaw,
            head_yaw: yaw,
            prev_head_yaw: yaw,
            health: 20.0,
            velocity: [0.0; 3],
            sound_timer: 2.0 + (id as f32 % 5.0),
            wander: (id as f32 * 1.7).sin() * std::f32::consts::TAU,
        }
    }

    fn snapshot(&self) -> EntitySnapshot {
        EntitySnapshot {
            id: self.id,
            player: false,
            uuid: [0; 16],
            prev: self.prev,
            position: self.position,
            prev_yaw: self.prev_yaw,
            yaw: self.yaw,
            head_yaw: self.head_yaw,
            prev_head_yaw: self.prev_head_yaw,
            pitch: 0.0,
            kind: self.kind,
            item: None,
            name: String::new(),
            show_name: false,
            health: self.health,
            flags: 0,
            held_item: None,
            armor: [None; 4],
            item_frame: None,
            velocity: self.velocity,
            animation: 0,
            animation_ticks: 0,
        }
    }
}

fn sync_local_block_entity(
    block_entities: &mut HashMap<(i32, i32, i32), BlockEntity>,
    x: i32,
    y: i32,
    z: i32,
    block: BlockState,
) {
    block_entities.remove(&(x, y, z));
    if let Some(entity) = BlockEntity::from_block(x, y, z, block) {
        block_entities.insert((x, y, z), entity);
    }
}

/// Pick the 1.8 `dig.*` / `step.*` family for a block. `placing` selects a
/// slightly quieter cue, but vanilla uses the same material family either way.
fn block_sound_event(block: BlockState, _placing: bool) -> &'static str {
    let name = nephele_world::blocks::name(block.id());
    if name.contains("glass") {
        "dig.glass"
    } else if name.contains("snow") || name.contains("ice") {
        "dig.snow"
    } else if name.contains("sand") {
        "dig.sand"
    } else if name.contains("gravel") {
        "dig.gravel"
    } else if name.contains("grass") {
        "dig.grass"
    } else if name.contains("wool") || name.contains("cloth") {
        "dig.cloth"
    } else if name.contains("wood") || name.contains("log") || name.contains("planks") {
        "dig.wood"
    } else {
        "dig.stone"
    }
}

fn world_light(time_of_day: i64) -> f32 {
    if is_night(time_of_day) {
        0.28
    } else {
        let time = time_of_day.rem_euclid(24_000) as f32;
        // Fade between the day level and night level around dawn/dusk.
        let day = 1.0;
        let night = 0.28;
        if (12_000.0..13_500.0).contains(&time) {
            day + (night - day) * ((time - 12_000.0) / 1_500.0)
        } else if (22_500.0..24_000.0).contains(&time) {
            night + (day - night) * ((time - 22_500.0) / 1_500.0)
        } else {
            day
        }
    }
}

fn sky_color(time_of_day: i64) -> [f32; 3] {
    let time = time_of_day.rem_euclid(24_000) as f32;
    let day = [0.42, 0.62, 0.96];
    let night = [0.015, 0.025, 0.075];
    let dusk = [0.68, 0.28, 0.12];
    if (12_000.0..13_500.0).contains(&time) || (22_500.0..24_000.0).contains(&time) {
        let t = if time >= 22_500.0 {
            (time - 22_500.0) / 1_500.0
        } else {
            (time - 12_000.0) / 1_500.0
        };
        [
            day[0] + (dusk[0] - day[0]) * t,
            day[1] + (dusk[1] - day[1]) * t,
            day[2] + (dusk[2] - day[2]) * t,
        ]
    } else if is_night(time_of_day) {
        night
    } else {
        day
    }
}

fn is_night(time_of_day: i64) -> bool {
    let time = time_of_day.rem_euclid(24_000);
    (13_000..23_000).contains(&time)
}

fn hostile(kind: u8) -> bool {
    matches!(kind, 50 | 51 | 52 | 54 | 59)
}

fn local_mob_event(kind: u8) -> &'static str {
    match kind {
        50 => "mob.creeper.say",
        51 => "mob.skeleton.say",
        52 | 59 => "mob.spider.say",
        54 => "mob.zombie.say",
        90 => "mob.pig.say",
        91 => "mob.sheep.say",
        92 => "mob.cow.say",
        93 => "mob.chicken.say",
        94 => "mob.squid.say",
        _ => "mob.zombie.say",
    }
}

fn random_unit(seed: u64) -> f32 {
    let mut value = seed.wrapping_mul(6_364_136_223_846_793_005).wrapping_add(1);
    value ^= value >> 33;
    value = value.wrapping_mul(0xff51_afd7_ed55_8ccd);
    value ^= value >> 33;
    (value & 0xFFFF) as f32 / 65_535.0
}

fn tick_local_mobs(
    mobs: &mut Vec<LocalMob>,
    world: &World,
    player: [f64; 3],
    night: bool,
    ticks: u64,
    seed: u64,
) -> Vec<play::SoundEffect> {
    let mut sounds = Vec::new();
    if night && mobs.len() < 8 && ticks % 40 == 0 {
        let angle = random_unit(seed ^ ticks) * std::f32::consts::TAU;
        let distance = 8.0 + random_unit(seed ^ (ticks << 7)) * 10.0;
        let x = player[0] + angle.cos() as f64 * distance as f64;
        let z = player[2] + angle.sin() as f64 * distance as f64;
        if let Some(height) = world.height_at(x.floor() as i32, z.floor() as i32) {
            let kinds = [54, 51, 50, 52];
            let kind = kinds[(random_unit(seed ^ (ticks << 11)) * 4.0) as usize % 4];
            let mut mob = LocalMob::new(
                10_000 + (ticks as i32 % 40_000),
                kind,
                [x, height as f64 + 1.0, z],
            );
            mob.wander = angle;
            mobs.push(mob);
        }
    }
    if !night {
        mobs.retain(|mob| !hostile(mob.kind));
    }
    for mob in mobs.iter_mut() {
        mob.prev = mob.position;
        mob.prev_yaw = mob.yaw;
        mob.prev_head_yaw = mob.head_yaw;
        let dx = player[0] - mob.position[0];
        let dz = player[2] - mob.position[2];
        let distance = (dx * dx + dz * dz).sqrt();
        let (dir_x, dir_z) = if hostile(mob.kind) && distance < 24.0 && distance > 0.01 {
            (dx / distance, dz / distance)
        } else {
            mob.wander += 0.008;
            (mob.wander.cos() as f64, mob.wander.sin() as f64)
        };
        let speed = if hostile(mob.kind) { 0.055 } else { 0.035 };
        mob.position[0] += dir_x * speed;
        mob.position[2] += dir_z * speed;
        if let Some(height) = world.height_at(
            mob.position[0].floor() as i32,
            mob.position[2].floor() as i32,
        ) {
            mob.position[1] = height as f64 + 1.0;
        }
        mob.yaw = ((-dir_x).atan2(dir_z).to_degrees() as f32).rem_euclid(360.0);
        mob.head_yaw = mob.yaw;
        mob.velocity = [dir_x * speed * 20.0, 0.0, dir_z * speed * 20.0];
        mob.sound_timer -= 0.05;
        if mob.sound_timer <= 0.0 && distance < 28.0 {
            sounds.push(play::SoundEffect {
                name: local_mob_event(mob.kind).to_string(),
                x: mob.position[0],
                y: mob.position[1] + 1.0,
                z: mob.position[2],
                volume: 0.9,
                pitch: 0.9 + random_unit(seed ^ mob.id as u64) * 0.2,
            });
            mob.sound_timer = 4.0 + random_unit(seed ^ (mob.id as u64).wrapping_mul(7)) * 5.0;
        }
    }
    sounds
}

/// Single-player: generate terrain around the player, simulate, and let them
/// mine and place without a server.
fn local_loop(
    mut save: WorldSave,
    shared: Arc<Mutex<Shared>>,
    tx: Sender<NetMsg>,
) -> Result<(), String> {
    use nephele_protocol::packets::play::HOTBAR_FIRST_SLOT;
    use nephele_world::{BlockState, ChunkCoord, TerrainGenerator};

    let seed = save.metadata().seed;
    let mode = save.metadata().mode;
    let generator = TerrainGenerator::new(seed);
    let mut world = World::new(0);
    // Honour the render-distance setting; `radius` is re-read every tick so
    // changing it in Options takes effect without restarting the world.
    let mut radius;

    {
        let mut state = shared.lock().unwrap();
        let spawn_y = generator.spawn_height() as f64;
        state.player.teleport(0.5, spawn_y, 0.5);
        state.spawned = true;
        state.creative = mode.is_creative();
        state.status = format!("{} (seed {seed})", save.metadata().name);
        state.inventory.fill(None);
        if mode.is_creative() {
            for (index, block) in nephele_client::STARTER_HOTBAR.iter().enumerate() {
                state.inventory[HOTBAR_FIRST_SLOT + index] =
                    Some(ItemStack::new(block.id() as i16, 64, block.meta() as i16));
            }
        }
        refresh_local_crafting_preview(&mut state);
    }

    let mut sent: HashSet<(i32, i32)> = HashSet::new();
    let mut miner = Miner::default();
    let mut mobs: Vec<LocalMob> = Vec::new();
    let mut block_entities: HashMap<(i32, i32, i32), BlockEntity> = HashMap::new();
    let mut ticks = 0u64;
    let mut last_step = [0.5, 80.0, 0.5];
    let mut step_distance = 0.0f64;
    let mut last_health = 20.0f32;

    loop {
        ticks = ticks.wrapping_add(1);
        let (position, yaw, pitch, _on_ground) = step_player(&shared, &world);
        radius = local_stream_radius(&shared.lock().unwrap());
        let night = {
            let mut state = shared.lock().unwrap();
            if let Some(time) = state.time_override.take() {
                state.time_of_day = time.rem_euclid(24_000);
            } else {
                state.time_of_day = (state.time_of_day + 20).rem_euclid(24_000);
            }
            is_night(state.time_of_day)
        };

        // Stream generated columns around the player.
        let centre = (
            (position.x / 16.0).floor() as i32,
            (position.z / 16.0).floor() as i32,
        );
        let mut columns = Vec::new();
        for dx in -radius..=radius {
            for dz in -radius..=radius {
                let coord = (centre.0 + dx, centre.1 + dz);
                if !sent.insert(coord) {
                    continue;
                }
                let column = match save.load_chunk(coord.0, coord.1) {
                    Ok(Some(column)) => column,
                    Ok(None) => generator.column(coord.0, coord.1),
                    Err(error) => return Err(error.to_string()),
                };
                world.insert(column.clone());
                columns.push(column);
            }
        }
        let stale: Vec<(i32, i32)> = sent
            .iter()
            .copied()
            .filter(|(x, z)| (x - centre.0).abs() > radius + 2 || (z - centre.1).abs() > radius + 2)
            .collect();
        for coord in stale {
            sent.remove(&coord);
            world.remove(ChunkCoord::new(coord.0, coord.1));
            let _ = tx.send(NetMsg::Unload(coord.0, coord.1));
        }
        if !columns.is_empty() {
            let _ = tx.send(NetMsg::Chunks(columns));
        }

        let sounds = tick_local_mobs(
            &mut mobs,
            &world,
            [position.x, position.y, position.z],
            night,
            ticks,
            seed,
        );
        let _ = tx.send(NetMsg::Entities(
            mobs.iter().map(LocalMob::snapshot).collect(),
        ));
        for sound in sounds {
            let _ = tx.send(NetMsg::Sound(sound));
        }
        let _ = tx.send(NetMsg::BlockEntities(
            block_entities.values().cloned().collect(),
        ));

        // What are we looking at?
        let eye = [position.x, position.y + EYE_HEIGHT, position.z];
        let direction = look_direction(yaw, pitch);
        let reach = if shared.lock().unwrap().creative {
            REACH_CREATIVE
        } else {
            REACH_SURVIVAL
        };
        let aim = raycast(&world, eye, direction, reach).map(|hit| Aim {
            x: hit.x,
            y: hit.y,
            z: hit.z,
            face: hit.face.protocol_id(),
            cursor: [
                (hit.point[0] - hit.x as f64).clamp(0.0, 1.0) as f32,
                (hit.point[1] - hit.y as f64).clamp(0.0, 1.0) as f32,
                (hit.point[2] - hit.z as f64).clamp(0.0, 1.0) as f32,
            ],
        });

        let (attacking, use_pressed, pending_slot, give, chat, edits, gamemode) = {
            let mut state = shared.lock().unwrap();
            (
                state.attacking,
                std::mem::take(&mut state.use_pressed),
                state.pending_slot.take(),
                state.give_item.take(),
                std::mem::take(&mut state.chat_out),
                std::mem::take(&mut state.world_edits),
                state.creative_override.take(),
            )
        };
        if let Some(slot) = pending_slot {
            shared.lock().unwrap().held_slot = slot;
        }
        if let Some((slot, item)) = give {
            let mut state = shared.lock().unwrap();
            if let Some(entry) = state.inventory.get_mut(slot as usize) {
                *entry = Some(item);
            }
        }
        if let Some(creative) = gamemode {
            shared.lock().unwrap().creative = creative;
            let mode = if creative {
                WorldMode::Creative
            } else {
                WorldMode::Survival
            };
            save.set_mode(mode).map_err(|error| error.to_string())?;
        }
        for line in chat {
            // Singleplayer has no chat server; echo it like one would.
            let _ = tx.send(NetMsg::Chat(line));
        }

        let mut dirty: HashSet<(i32, i32)> = HashSet::new();
        for (x, y, z, state) in edits {
            let block = BlockState::from_raw(state);
            world.set_block(x, y, z, block);
            sync_local_block_entity(&mut block_entities, x, y, z, block);
            dirty.insert((x.div_euclid(16), z.div_euclid(16)));
        }
        let creative = shared.lock().unwrap().creative;
        for event in miner.tick(&world, aim, attacking, creative) {
            if let MiningEvent::Stop(target) = event {
                let broken = world.get_block(target.x, target.y, target.z);
                world.set_block(target.x, target.y, target.z, BlockState::AIR);
                block_entities.remove(&(target.x, target.y, target.z));
                dirty.insert((target.x.div_euclid(16), target.z.div_euclid(16)));
                let _ = tx.send(NetMsg::Particles(vec![play::ParticleSpawn {
                    particle_id: 37,
                    long_distance: false,
                    x: target.x as f32 + 0.5,
                    y: target.y as f32 + 0.5,
                    z: target.z as f32 + 0.5,
                    offset_x: 0.4,
                    offset_y: 0.4,
                    offset_z: 0.4,
                    speed: 0.08,
                    count: 12,
                    arguments: vec![broken.raw() as i32],
                }]));
                let _ = tx.send(NetMsg::Sound(play::SoundEffect {
                    name: block_sound_event(broken, false).to_string(),
                    x: target.x as f64 + 0.5,
                    y: target.y as f64 + 0.5,
                    z: target.z as f64 + 0.5,
                    volume: 0.8,
                    pitch: 1.0,
                }));
                if !creative {
                    if let Some(item) = local_block_drop(broken) {
                        add_local_item(&mut shared.lock().unwrap(), item);
                    }
                }
            }
        }
        if use_pressed {
            if let Some(aim) = aim {
                let targeted = world.get_block(aim.x, aim.y, aim.z);
                if nephele_world::shapes::is_door(targeted.id()) {
                    if nephele_world::shapes::toggle_door_open(&mut world, aim.x, aim.y, aim.z) {
                        dirty.insert((aim.x.div_euclid(16), aim.z.div_euclid(16)));
                    }
                } else if targeted.id() == nephele_world::crafting::CRAFTING_TABLE {
                    let mut state = shared.lock().unwrap();
                    if state.window_id.is_none() {
                        open_local_crafting_table(&mut state);
                    }
                } else {
                    let (held_slot, held) = {
                        let state = shared.lock().unwrap();
                        let slot = HOTBAR_FIRST_SLOT + (state.held_slot.clamp(0, 8) as usize);
                        (slot, state.inventory.get(slot).copied().flatten())
                    };
                    if let Some(state_block) = held.and_then(|item| item.block_state()) {
                        let normal = nephele_world::Face::from_protocol_id(aim.face)
                            .map(|face| face.normal())
                            .unwrap_or([0, 1, 0]);
                        let (bx, by, bz) =
                            (aim.x + normal[0], aim.y + normal[1], aim.z + normal[2]);
                        let player_feet = [position.x, position.y, position.z];
                        let block = BlockState::from_raw(state_block);
                        if nephele_world::shapes::is_door(block.id()) {
                            if !door_placement_hits_player(bx, by, bz, player_feet)
                                && nephele_world::shapes::place_door(
                                    &mut world,
                                    bx,
                                    by,
                                    bz,
                                    block.id(),
                                    yaw,
                                )
                            {
                                dirty.insert((bx.div_euclid(16), bz.div_euclid(16)));
                                if !creative {
                                    consume_held_block(
                                        &mut shared.lock().unwrap(),
                                        held_slot,
                                        state_block,
                                    );
                                }
                            }
                        } else if world.get_block(bx, by, bz).is_air()
                            && !placement_hits_player(&aim, player_feet)
                        {
                            world.set_block(bx, by, bz, block);
                            sync_local_block_entity(&mut block_entities, bx, by, bz, block);
                            dirty.insert((bx.div_euclid(16), bz.div_euclid(16)));
                            let _ = tx.send(NetMsg::Sound(play::SoundEffect {
                                name: block_sound_event(block, true).to_string(),
                                x: bx as f64 + 0.5,
                                y: by as f64 + 0.5,
                                z: bz as f64 + 0.5,
                                volume: 0.65,
                                pitch: 1.0,
                            }));
                            if !creative {
                                consume_held_block(
                                    &mut shared.lock().unwrap(),
                                    held_slot,
                                    state_block,
                                );
                            }
                        }
                    }
                }
            }
        }
        for (cx, cz) in dirty {
            if let Some(column) = world.get(ChunkCoord::new(cx, cz)) {
                save.save_chunk(column).map_err(|error| error.to_string())?;
                let _ = tx.send(NetMsg::Chunks(vec![column.clone()]));
            }
        }

        let dx = position.x - last_step[0];
        let dz = position.z - last_step[2];
        step_distance += (dx * dx + dz * dz).sqrt();
        if step_distance >= 1.8 {
            step_distance = 0.0;
            let below = world.get_block(
                position.x.floor() as i32,
                (position.y - 1.0).floor() as i32,
                position.z.floor() as i32,
            );
            let _ = tx.send(NetMsg::Sound(play::SoundEffect {
                name: block_sound_event(below, false).replacen("dig.", "step.", 1),
                x: position.x,
                y: position.y,
                z: position.z,
                volume: 0.35,
                pitch: 1.0,
            }));
        }
        last_step = [position.x, position.y, position.z];

        {
            let mut state = shared.lock().unwrap();
            if state.health < last_health {
                let _ = tx.send(NetMsg::Sound(play::SoundEffect {
                    name: "game.player.hurt".to_string(),
                    x: position.x,
                    y: position.y + 1.0,
                    z: position.z,
                    volume: 1.0,
                    pitch: 1.0,
                }));
            }
            last_health = state.health;
            state.aim = aim;
            state.break_stage = miner.stage();
            state.chunks = world.loaded_chunks();
        }

        std::thread::sleep(TICK);
    }
}

/// Camera-relative look vector, matching [`Camera::forward`].
fn look_direction(yaw: f32, pitch: f32) -> [f64; 3] {
    let (sin_yaw, cos_yaw) = yaw.sin_cos();
    let (sin_pitch, cos_pitch) = pitch.sin_cos();
    [
        (sin_yaw * cos_pitch) as f64,
        sin_pitch as f64,
        (-cos_yaw * cos_pitch) as f64,
    ]
}

async fn net_loop(
    address: ServerAddress,
    username: String,
    session_path: Option<std::path::PathBuf>,
    shared: Arc<Mutex<Shared>>,
    tx: Sender<NetMsg>,
) -> Result<(), String> {
    let mut client = match &session_path {
        Some(path) => {
            let stored = nephele_auth::StoredSession::load(path)
                .map_err(|err| format!("no Microsoft session ({err}); run `nephele auth` first"))?;
            GameClient::join_online(&address, &stored.session())
                .await
                .map_err(|err| err.to_string())?
        }
        None => GameClient::join(&address, &username)
            .await
            .map_err(|err| err.to_string())?,
    };

    let mut creative = client.is_creative();
    if creative {
        if let Err(err) = client.give_starter_hotbar().await {
            eprintln!("could not fill the creative hotbar: {err}");
        }
    }
    {
        let mut state = shared.lock().unwrap();
        state.status = format!("{} @ {}", client.info.username, address);
        state.creative = creative;
    }

    let mut miner = Miner::default();
    let mut world_dirty = false;
    let mut sent_view_distance = shared.lock().unwrap().view_distance;

    // Chunks we've already handed to the renderer. Diffing against the world
    // each tick catches bulk loads, which only report their last column.
    let mut sent: HashSet<(i32, i32)> = HashSet::new();
    let mut ticker = tokio::time::interval(TICK);
    ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let (position, yaw, pitch, on_ground) = step_player(&shared, &client.world);
                let (attacking, use_pressed, pending_slot, give, chat, edits, gamemode, clicks) = {
                    let mut state = shared.lock().unwrap();
                    (
                        state.attacking,
                        std::mem::take(&mut state.use_pressed),
                        state.pending_slot.take(),
                        state.give_item.take(),
                        std::mem::take(&mut state.chat_out),
                        std::mem::take(&mut state.world_edits),
                        state.creative_override.take(),
                        std::mem::take(&mut state.inventory_clicks),
                    )
                };
                for (slot, button, mode, clicked) in clicks {
                    client
                        .click_slot_with(slot, button, mode, clicked)
                        .await
                        .map_err(|err| err.to_string())?;
                }
                if std::mem::take(&mut shared.lock().unwrap().close_window) {
                    client
                        .close_container()
                        .await
                        .map_err(|err| err.to_string())?;
                }
                for line in chat {
                    client
                        .send_chat(&line)
                        .await
                        .map_err(|err| err.to_string())?;
                }
                for (x, y, z, state) in edits {
                    client
                        .world
                        .set_block(x, y, z, nephele_world::BlockState::from_raw(state));
                    world_dirty = true;
                }
                if let Some(creative_flag) = gamemode {
                    client.info.gamemode = if creative_flag { 1 } else { 0 };
                    creative = creative_flag;
                    shared.lock().unwrap().creative = creative_flag;
                }

                let requested_view_distance = shared.lock().unwrap().view_distance;
                if requested_view_distance != sent_view_distance {
                    client
                        .send_client_settings(requested_view_distance)
                        .await
                        .map_err(|err| err.to_string())?;
                    sent_view_distance = requested_view_distance;
                }

                if let Some(slot) = pending_slot {
                    client
                        .set_held_slot(slot)
                        .await
                        .map_err(|err| err.to_string())?;
                }

                if let Some((slot, item)) = give {
                    client
                        .creative_set_slot(slot, Some(item))
                        .await
                        .map_err(|err| err.to_string())?;
                }

                // What are we looking at?
                let eye = [position.x, position.y + EYE_HEIGHT, position.z];
                let direction = look_direction(yaw, pitch);
                let reach = if creative { REACH_CREATIVE } else { REACH_SURVIVAL };
                let aim = raycast(&client.world, eye, direction, reach).map(|hit| Aim {
                    x: hit.x,
                    y: hit.y,
                    z: hit.z,
                    face: hit.face.protocol_id(),
                    cursor: [
                        (hit.point[0] - hit.x as f64).clamp(0.0, 1.0) as f32,
                        (hit.point[1] - hit.y as f64).clamp(0.0, 1.0) as f32,
                        (hit.point[2] - hit.z as f64).clamp(0.0, 1.0) as f32,
                    ],
                });

                for event in miner.tick(&client.world, aim, attacking, creative) {
                    match event {
                        MiningEvent::Start(target) => {
                            client.dig(digging::START_DESTROY_BLOCK, &target).await
                                .map_err(|err| err.to_string())?;
                            client.swing().await.map_err(|err| err.to_string())?;
                        }
                        MiningEvent::Stop(target) => {
                            client.dig(digging::STOP_DESTROY_BLOCK, &target).await
                                .map_err(|err| err.to_string())?;
                        }
                        MiningEvent::Abort(target) => {
                            client.dig(digging::ABORT_DESTROY_BLOCK, &target).await
                                .map_err(|err| err.to_string())?;
                        }
                    }
                }

                if use_pressed {
                    if let Some(target) = aim {
                        if !placement_hits_player(&target, [position.x, position.y, position.z]) {
                            let placeable = client
                                .held_item()
                                .and_then(|item| item.block_state())
                                .is_some();
                            if placeable {
                                client
                                    .place(&target)
                                    .await
                                    .map_err(|err| err.to_string())?;
                            } else {
                                client
                                    .use_block(&target)
                                    .await
                                    .map_err(|err| err.to_string())?;
                            }
                        }
                    }
                }

                client
                    .send_move(position, yaw, pitch, on_ground)
                    .await
                    .map_err(|err| err.to_string())?;

                // One client tick: snapshot every entity's interpolation start,
                // then hand the whole table to the renderer.
                client.entities.tick();
                let snapshot: Vec<EntitySnapshot> = client
                    .entities
                    .iter()
                    .map(EntitySnapshot::from_entity)
                    .collect();
                if std::mem::take(&mut shared.lock().unwrap().pending_respawn) {
                    client.respawn().await.map_err(|err| err.to_string())?;
                }
                let _ = tx.send(NetMsg::Entities(snapshot));
                let block_entities: Vec<BlockEntity> =
                    client.block_entity_views.values().cloned().collect();
                let _ = tx.send(NetMsg::BlockEntities(block_entities));

                {
                    let mut state = shared.lock().unwrap();
                    state.aim = aim;
                    state.break_stage = miner.stage();
                    state.held_slot = client.held_slot;
                    state.health = client.health;
                    state.food = client.food;
                    state.xp_bar = client.xp_bar;
                    state.xp_level = client.xp_level;
                    state.time_of_day = client.time_of_day.rem_euclid(24_000);
                    state.chunks = client.world.loaded_chunks();
                    if state.inventory.len() != client.inventory.len() {
                        state.inventory = client.inventory.clone();
                    } else {
                        state.inventory.copy_from_slice(&client.inventory);
                    }
                    state.window_id = client.open_window.as_ref().map(|open| open.id);
                    state.window_open = state.window_id.is_some();
                    state.window_slots = client
                        .open_window
                        .as_ref()
                        .map(|open| open.slots.clone())
                        .unwrap_or_default();
                }

                let mut batch = Vec::new();
                for (coord, column) in client.world.iter() {
                    if !sent.contains(&(coord.x, coord.z)) {
                        batch.push(column.clone());
                    }
                }
                if world_dirty {
                    // A block changed somewhere: re-send what the renderer has
                    // so its copy of the world matches the server's.
                    world_dirty = false;
                    for (coord, column) in client.world.iter() {
                        if sent.contains(&(coord.x, coord.z)) {
                            batch.push(column.clone());
                        }
                    }
                }
                if !batch.is_empty() {
                    for column in &batch {
                        sent.insert((column.x, column.z));
                    }
                    let _ = tx.send(NetMsg::Chunks(batch));
                }

                let stale: Vec<(i32, i32)> = sent
                    .iter()
                    .copied()
                    .filter(|(x, z)| !client.world.contains(ChunkCoord::new(*x, *z)))
                    .collect();
                for (x, z) in stale {
                    sent.remove(&(x, z));
                    let _ = tx.send(NetMsg::Unload(x, z));
                }
            }
            event = client.tick(Duration::from_millis(100)) => {
                match event {
                    Ok(Event::Position { position, yaw, pitch }) => {
                        let mut state = shared.lock().unwrap();
                        state.teleport = Some([position.x, position.y, position.z]);
                        state.yaw = yaw;
                        state.pitch = pitch;
                        state.spawned = true;
                    }
                    Ok(Event::Chat(text)) => {
                        let _ = tx.send(NetMsg::Chat(text));
                    }
                    Ok(Event::BlocksChanged(_)) => {
                        world_dirty = true;
                    }
                    Ok(Event::Particles(particles)) => {
                        let _ = tx.send(NetMsg::Particles(particles));
                    }
                    Ok(Event::SoundEffect(sound)) => {
                        let _ = tx.send(NetMsg::Sound(sound));
                    }
                    Ok(Event::PlayerList) => {
                        let skins: Vec<([u8; 16], String, bool)> = client
                            .skins
                            .iter()
                            .filter_map(|(uuid, info)| {
                                info.hash.clone().map(|hash| (*uuid, hash, info.slim))
                            })
                            .collect();
                        if !skins.is_empty() {
                            let _ = tx.send(NetMsg::Skins(skins));
                        }
                    }
                    Ok(Event::MapUpdated { map_id }) => {
                        if let Some(state) = client.maps.get(map_id).cloned() {
                            let _ = tx.send(NetMsg::Map(map_id, state));
                        }
                    }
                    Ok(_) => {}
                    Err(err) => return Err(err.to_string()),
                }
            }
        }
    }
}

/// One line of the on-screen chat log.
struct ChatLine {
    text: String,
    at: Instant,
}

/// Everything one frame needs from the game thread.
struct FrameView {
    camera: Camera,
    status: String,
    error: Option<String>,
    aim: Option<Aim>,
    stage: Option<u8>,
    held_slot: i16,
    creative: bool,
    /// Left mouse held: drives both the miner and the first-person swing.
    attacking: bool,
    /// Stack shown under the pointer in the inventory screen.
    inventory_cursor: Option<ItemStack>,
    inventory: Vec<Option<ItemStack>>,
    window_open: bool,
    window_slots: Vec<Option<ItemStack>>,
    health: f32,
    food: i32,
    xp_bar: f32,
    xp_level: i32,
    chunks: usize,
    feet: [f64; 3],
    /// Fraction of the way through the current 20 Hz tick.
    alpha: f64,
    time_of_day: i64,
}

struct LiveApp {
    options: PlayOptions,
    shared: Arc<Mutex<Shared>>,
    rx: Receiver<NetMsg>,
    window: Option<Arc<Window>>,
    renderer: Option<Renderer>,
    textures: Option<Arc<TextureArray>>,
    world: World,
    /// Columns whose mesh needs rebuilding, ordered farâ†’near so `pop()` hands
    /// the nearest chunk to the mesher first.
    dirty_chunks: Vec<(i32, i32)>,
    /// Columns currently somewhere in the meshing pipeline.
    queued: HashSet<(i32, i32)>,
    /// Columns edited while a worker was already meshing them; their result is
    /// out of date and gets rebuilt once it comes back.
    stale: HashSet<(i32, i32)>,
    mesh_pool: Option<MeshPool>,
    /// Remote entities, replaced on every network tick.
    entities: Vec<EntitySnapshot>,
    /// Block entities from the server or the local world.
    block_entities: Vec<BlockEntity>,
    particles: Particles,
    audio: Option<AudioEngine>,
    /// Packed player skins and the atlas slot each player occupies.
    skin_atlas: SkinAtlas,
    skin_slots: std::collections::HashMap<[u8; 16], u32>,
    /// Whether each player's skin uses the slim arm layout.
    skin_slim: std::collections::HashMap<[u8; 16], bool>,
    /// Map pixels and the atlas slot each map id occupies.
    maps: Maps,
    map_slots: std::collections::HashMap<i32, u32>,
    mob_slots: std::collections::HashMap<u8, u32>,
    sign_slot: u32,
    chest_slot: u32,
    banner_slot: u32,
    beacon_beam_slot: u32,
    book_slot: u32,
    item_frame_slot: u32,
    skin_loader: SkinLoader,
    /// Per-phase frame timings, printed once a second under `NEPHELE_PROFILE=1`.
    profile: bool,
    prof_ui: f32,
    prof_mesh: f32,
    prof_draw: f32,
    prof_frames: u32,
    keys: HashSet<KeyCode>,
    mouse_captured: bool,
    last_cursor: Option<PhysicalPosition<f64>>,
    /// True once the platform started reporting raw mouse deltas; from then on
    /// CursorMoved is only used for the menu pointer.
    raw_motion: bool,
    last_frame: Instant,
    title_timer: f32,
    frames: u32,
    drawn_aim: Option<Aim>,
    drawn_stage: Option<u8>,
    ui_bg: UiBatch,
    ui_icons: UiBatch,
    ui_fg: UiBatch,
    buttons: Vec<ui::Button>,
    screen: Screen,
    tx: Sender<NetMsg>,
    splash: String,
    time: f32,
    address_input: String,
    /// Chat overlay: recent lines and the input line while it is open.
    chat_open: bool,
    chat_input: String,
    chat_log: std::collections::VecDeque<ChatLine>,
    /// Saved servers behind the multiplayer screen.
    servers: ServerList,
    /// First visible row of `servers`.
    servers_scroll: usize,
    /// Address of the selected server, not its index: indices shift when an
    /// entry is deleted or a favourite re-sorts the list.
    servers_selected: Option<String>,
    /// Ping results, filled in asynchronously by `spawn_ping`.
    pings: PingBoard,
    ping_tx: Sender<PingReply>,
    ping_rx: Receiver<PingReply>,
    /// Previous row click, for the double-click-to-join gesture.
    last_server_click: Option<(Instant, String)>,
    settings_return: Screen,
    /// When the window last gained focus; clicks right after it are ignored.
    focus_gained: Option<Instant>,
    settings: Settings,
    saves_dir: std::path::PathBuf,
    worlds: Vec<WorldMetadata>,
    worlds_scroll: usize,
    world_error: Option<String>,
    world_name_input: String,
    world_seed_input: String,
    world_create_mode: WorldMode,
    world_name_focused: bool,
    world_seed_focused: bool,
    pointer: Option<[f32; 2]>,
    creative_page: usize,
    /// Stack held on the cursor in the inventory screen (client-side only).
    inventory_cursor: Option<ItemStack>,
    /// Shift held down, for inventory quick-move clicks.
    shift: bool,
    last_fps: f32,
    error: Option<Box<dyn Error>>,
}

impl LiveApp {
    fn new(
        options: PlayOptions,
        shared: Arc<Mutex<Shared>>,
        rx: Receiver<NetMsg>,
        tx: Sender<NetMsg>,
        settings: Settings,
    ) -> Self {
        let env_screen = match std::env::var("NEPHELE_SCREEN").as_deref() {
            Ok("creative") => Some(Screen::Creative),
            Ok("pause") => Some(Screen::Pause),
            Ok("settings") => Some(Screen::Settings),
            Ok("connect") => Some(Screen::Connect),
            Ok("servers") => Some(Screen::Servers),
            Ok("worlds") => Some(Screen::Worlds),
            Ok("world_create") => Some(Screen::WorldCreate),
            Ok("game") => Some(Screen::Game),
            Ok("title") => Some(Screen::Title),
            _ => None,
        };

        let saves_dir = crate::paths::user_data_dir().join("saves");
        let world_seed_input = options
            .seed
            .map(|seed| seed.to_string())
            .unwrap_or_default();
        let servers = ServerList::load(&options.servers_path);
        let (ping_tx, ping_rx) = mpsc::channel();
        let audio_root = options
            .assets_dir
            .parent()
            .and_then(|textures| textures.parent())
            .map(|minecraft| minecraft.to_path_buf())
            .unwrap_or_else(|| options.assets_dir.clone());
        let audio = Some(AudioEngine::new(&audio_root));

        let has_address = options.address.is_some();
        let mut app = Self {
            options,
            shared,
            rx,
            window: None,
            renderer: None,
            textures: None,
            world: World::new(0),
            dirty_chunks: Vec::new(),
            queued: HashSet::new(),
            stale: HashSet::new(),
            mesh_pool: None,
            entities: Vec::new(),
            block_entities: Vec::new(),
            particles: Particles::new(),
            audio,
            skin_atlas: SkinAtlas::new(),
            skin_slots: std::collections::HashMap::new(),
            skin_slim: std::collections::HashMap::new(),
            maps: Maps::new(),
            map_slots: std::collections::HashMap::new(),
            mob_slots: std::collections::HashMap::new(),
            sign_slot: SkinAtlas::DEFAULT_SLOT,
            chest_slot: SkinAtlas::DEFAULT_SLOT,
            banner_slot: SkinAtlas::DEFAULT_SLOT,
            beacon_beam_slot: SkinAtlas::DEFAULT_SLOT,
            book_slot: SkinAtlas::DEFAULT_SLOT,
            item_frame_slot: SkinAtlas::DEFAULT_SLOT,
            skin_loader: SkinLoader::new(),
            profile: std::env::var("NEPHELE_PROFILE").is_ok(),
            prof_ui: 0.0,
            prof_mesh: 0.0,
            prof_draw: 0.0,
            prof_frames: 0,
            keys: HashSet::new(),
            mouse_captured: false,
            last_cursor: None,
            raw_motion: false,
            last_frame: Instant::now(),
            title_timer: 0.0,
            frames: 0,
            drawn_aim: None,
            drawn_stage: None,
            ui_bg: UiBatch::default(),
            ui_icons: UiBatch::default(),
            ui_fg: UiBatch::default(),
            buttons: Vec::new(),
            screen: if has_address {
                Screen::Game
            } else {
                Screen::Title
            },
            tx,
            splash: String::new(),
            time: 0.0,
            address_input: String::new(),
            chat_open: false,
            chat_input: String::new(),
            chat_log: std::collections::VecDeque::new(),
            servers,
            servers_scroll: 0,
            servers_selected: None,
            pings: PingBoard::default(),
            ping_tx,
            ping_rx,
            last_server_click: None,
            settings_return: Screen::Pause,
            focus_gained: None,
            settings,
            saves_dir,
            worlds: Vec::new(),
            worlds_scroll: 0,
            world_error: None,
            world_name_input: String::new(),
            world_seed_input,
            world_create_mode: WorldMode::Creative,
            world_name_focused: true,
            world_seed_focused: false,
            pointer: None,
            creative_page: 0,
            inventory_cursor: None,
            shift: false,
            last_fps: 0.0,
            error: None,
        };

        if let Some(audio) = &app.audio {
            audio.set_master_volume(app.settings.volume);
        }
        if let Some(screen) = env_screen {
            app.screen = screen;
        }
        if app.screen == Screen::Servers {
            app.refresh_server_list();
        }
        if app.screen == Screen::Worlds {
            app.refresh_worlds();
        }
        if std::env::var("NEPHELE_SCREEN").as_deref() == Ok("local") {
            app.start_local();
        } else if has_address && env_screen.is_none() {
            if let Some(address) = app.options.address.clone() {
                app.start_network(address);
            }
        }
        app
    }

    fn fail(&mut self, event_loop: &ActiveEventLoop, err: impl Into<Box<dyn Error>>) {
        self.error = Some(err.into());
        event_loop.exit();
    }

    fn init(&mut self, event_loop: &ActiveEventLoop) {
        let window_start = Instant::now();
        let attributes = Window::default_attributes()
            .with_title("Nephele")
            .with_inner_size(LogicalSize::new(1280.0, 720.0));
        let window = match event_loop.create_window(attributes) {
            Ok(window) => Arc::new(window),
            Err(err) => return self.fail(event_loop, err),
        };
        perf::record_stage_span("window_init", window_start, Instant::now());

        let texture_decode_start = Instant::now();
        let textures = match TextureArray::load_from_dir(&self.options.assets_dir) {
            Ok(textures) => textures,
            Err(err) => return self.fail(event_loop, err),
        };
        perf::record_stage_span("texture_atlas_decode", texture_decode_start, Instant::now());
        // The UI sheets live one level up: `textures/font`, `textures/gui`.
        let ui_root = self
            .options
            .assets_dir
            .parent()
            .map(|path| path.to_path_buf())
            .unwrap_or_else(|| self.options.assets_dir.clone());
        let ui_decode_start = Instant::now();
        let ui_atlas = match UiAtlas::load(&ui_root) {
            Ok(atlas) => atlas,
            Err(err) => {
                return self.fail(event_loop, format!("could not build the UI atlas: {err}"));
            }
        };
        perf::record_stage_span("ui_atlas_decode", ui_decode_start, Instant::now());

        // Title screen art: the panorama cube and the splash line.
        let panorama = Panorama::load(&ui_root).ok();
        if let Ok(splashes) = SplashTexts::load(
            &ui_root
                .parent()
                .map(|p| p.join("texts"))
                .unwrap_or_else(|| ui_root.join("texts")),
        ) {
            let seed = self.options.seed.unwrap_or(0x5EED);
            self.splash = splashes.pick(seed).to_string();
        }

        let size = window.inner_size();
        let renderer_start = Instant::now();
        let mut renderer = match Renderer::new(
            window.clone(),
            size.width,
            size.height,
            &textures,
            &ui_atlas,
            panorama.as_ref(),
        ) {
            Ok(renderer) => renderer,
            Err(err) => return self.fail(event_loop, err),
        };
        perf::record_stage_span("renderer_init", renderer_start, Instant::now());
        for sample in renderer.startup_timings().samples() {
            let started = renderer_start + sample.start;
            let ended = started + sample.duration;
            perf::record_stage_span(sample.stage.name(), started, ended);
        }

        {
            let mut state = self.shared.lock().unwrap();
            state.player.flying = self.options.fly;
        }
        println!("Textures: {} layers.", textures.layer_count(),);

        renderer.set_panorama(false);

        let textures = Arc::new(textures);
        let pool = MeshPool::new(Arc::clone(&textures));
        if self.profile {
            println!("Meshing on {} worker threads.", pool.workers());
        }
        self.mesh_pool = Some(pool);
        self.textures = Some(textures);
        self.window = Some(window);

        // Upload the stand-in skin immediately; otherwise the entity atlas is
        // still all-transparent (and every humanoid is discarded) until the
        // first real skin downloads.
        let skin_upload_start = Instant::now();
        renderer.set_skins(&mut self.skin_atlas);
        perf::record_stage_span("texture_atlas_upload", skin_upload_start, Instant::now());
        self.renderer = Some(renderer);
        self.load_entity_textures();
    }

    fn set_mouse_capture(&mut self, captured: bool) {
        let Some(window) = self.window.clone() else {
            return;
        };
        self.mouse_captured = captured;
        if captured {
            let _ = window
                .set_cursor_grab(CursorGrabMode::Locked)
                .or_else(|_| window.set_cursor_grab(CursorGrabMode::Confined));
            window.set_cursor_visible(false);
            self.last_cursor = None;
        } else {
            let _ = window.set_cursor_grab(CursorGrabMode::None);
            window.set_cursor_visible(true);
            let mut state = self.shared.lock().unwrap();
            state.attacking = false;
        }
    }

    /// Queue a column for re-meshing.
    ///
    /// If a worker is already meshing that column the in-flight result will be
    /// out of date, so it is marked stale and rebuilt when it comes back.
    fn mark_dirty(&mut self, key: (i32, i32)) {
        if self.queued.insert(key) {
            self.dirty_chunks.push(key);
        } else if self
            .mesh_pool
            .as_ref()
            .is_some_and(|pool| pool.is_in_flight(key))
        {
            self.stale.insert(key);
        }
    }

    /// Re-mesh the four columns around `key`, when they are loaded.
    fn mark_neighbours_dirty(&mut self, key: (i32, i32)) {
        for (dx, dz) in [(-1, 0), (1, 0), (0, -1), (0, 1)] {
            let neighbour = (key.0 + dx, key.1 + dz);
            if self
                .world
                .contains(ChunkCoord::new(neighbour.0, neighbour.1))
            {
                self.mark_dirty(neighbour);
            }
        }
    }

    fn upload_chunk(&mut self, key: (i32, i32), mesh: &MeshData) {
        let min = [key.0 as f32 * 16.0, 0.0, key.1 as f32 * 16.0];
        let max = [min[0] + 16.0, 256.0, min[2] + 16.0];
        if let Some(renderer) = self.renderer.as_mut() {
            let upload_start = Instant::now();
            renderer.set_chunk(key, mesh, min, max);
            if !mesh.is_empty() {
                perf::record_chunk_upload(upload_start, upload_start.elapsed());
            }
        }
    }

    /// Apply any skins that finished downloading since the last frame, and
    /// drain the atlas upload budget. Calling this every frame guarantees a
    /// burst larger than the budget still finishes over the next few frames.
    fn update_skins(&mut self) {
        while let Some((hash, image)) = self.skin_loader.try_recv() {
            if let Some(slot) = self.skin_atlas.slot_of(&hash) {
                self.skin_atlas.set_skin(slot, &image);
            }
        }
        if let Some(renderer) = self.renderer.as_mut() {
            renderer.set_skins(&mut self.skin_atlas);
        }
    }

    /// Reserve an atlas slot for a map id, filling it with the server's pixels
    /// or the generated placeholder. The slot upload is budgeted by
    /// `Renderer::set_skins`, so a burst of maps does not block a frame.
    fn ensure_map_slot(&mut self, id: i32) -> u32 {
        if let Some(slot) = self.map_slots.get(&id) {
            return *slot;
        }
        let slot = self.skin_atlas.assign(&format!("map:{id}"));
        self.map_slots.insert(id, slot);
        self.upload_map(id, slot);
        slot
    }

    fn upload_map(&mut self, id: i32, slot: u32) {
        let data = self.maps.ensure(id).clone();
        let size = MapState::SIZE as u32;
        let Some(image) = image::RgbaImage::from_raw(size, size, data.to_rgba()) else {
            return;
        };
        self.skin_atlas.set_map(slot, &image);
        if let Some(renderer) = self.renderer.as_mut() {
            renderer.set_skins(&mut self.skin_atlas);
        }
    }

    /// Load the vanilla entity and block-entity textures into spare skin-atlas
    /// slots. Missing files are non-fatal: the model falls back to the stand-in
    /// skin and its flat tint.
    fn load_entity_textures(&mut self) {
        let Some(textures_root) = self.options.assets_dir.parent() else {
            return;
        };
        let entity_dir = textures_root.join("entity");
        let mut changed = false;
        let mobs: &[(u8, &str)] = &[
            (50, "creeper/creeper"),
            (51, "skeleton/skeleton"),
            (52, "spider/spider"),
            (54, "zombie/zombie"),
            (55, "slime/slime"),
            (58, "enderman/enderman"),
            (59, "spider/cave_spider"),
            (65, "bat"),
            (90, "pig/pig"),
            (91, "sheep/sheep"),
            (92, "cow/cow"),
            (93, "chicken"),
            (94, "squid"),
            (95, "wolf/wolf"),
        ];
        for &(kind, file) in mobs {
            let path = entity_dir.join(format!("{file}.png"));
            let Ok(image) = image::open(&path) else {
                continue;
            };
            let key = format!("mob:{kind}");
            let slot = self
                .skin_atlas
                .slot_of(&key)
                .unwrap_or_else(|| self.skin_atlas.assign(&key));
            self.skin_atlas
                .set_skin(slot, &crate::skins::normalise(image.to_rgba8()));
            self.mob_slots.insert(kind, slot);
            changed = true;
        }
        let block_entities: &[(&str, &str)] = &[
            ("sign", "sign"),
            ("chest", "chest/normal"),
            ("banner", "banner_base"),
            ("beacon_beam", "beacon_beam"),
            ("book", "enchanting_table_book"),
        ];
        for &(key, file) in block_entities {
            let path = entity_dir.join(format!("{file}.png"));
            let Ok(image) = image::open(&path) else {
                continue;
            };
            let slot = self
                .skin_atlas
                .slot_of(key)
                .unwrap_or_else(|| self.skin_atlas.assign(key));
            self.skin_atlas
                .set_skin(slot, &crate::skins::normalise(image.to_rgba8()));
            match key {
                "sign" => self.sign_slot = slot,
                "chest" => self.chest_slot = slot,
                "banner" => self.banner_slot = slot,
                "beacon_beam" => self.beacon_beam_slot = slot,
                "book" => self.book_slot = slot,
                "item_frame" => self.item_frame_slot = slot,
                _ => {}
            }
            changed = true;
        }
        // 1.8 has no entity/itemframe.png; the frame is the block texture.
        let frame_path = textures_root.join("blocks/itemframe_background.png");
        if let Ok(image) = image::open(&frame_path) {
            let slot = self
                .skin_atlas
                .slot_of("item_frame")
                .unwrap_or_else(|| self.skin_atlas.assign("item_frame"));
            self.skin_atlas
                .set_skin(slot, &crate::skins::normalise(image.to_rgba8()));
            self.item_frame_slot = slot;
            changed = true;
        }
        if changed {
            if let Some(renderer) = self.renderer.as_mut() {
                renderer.set_skins(&mut self.skin_atlas);
            }
        }
    }

    /// Rebuild every remote entity's geometry for this frame.
    ///
    /// Positions come from the 20 Hz network tick and are blended by `alpha`, so
    /// other players move as smoothly as the local camera does.
    fn draw_entities(&mut self, view: &FrameView) {
        let Some(textures) = self.textures.clone() else {
            return;
        };
        let alpha = view.alpha;

        // Reserve every map slot before borrowing the entity list. The upload
        // itself is budgeted by the renderer, so a lobby full of maps still
        // spreads across frames instead of stalling one.
        let mut map_ids = std::collections::HashSet::new();
        for entity in &self.entities {
            if let Some(id) = entity.held_item.and_then(|item| map_id_of(&item)) {
                map_ids.insert(id);
            }
            if let Some((_, _, Some(item))) = entity.item_frame {
                if let Some(id) = map_id_of(&item) {
                    map_ids.insert(id);
                }
            }
        }
        if let Some(id) = view
            .inventory
            .get(play::HOTBAR_FIRST_SLOT + view.held_slot.max(0) as usize)
            .copied()
            .flatten()
            .and_then(|item| map_id_of(&item))
        {
            map_ids.insert(id);
        }
        for id in map_ids {
            self.ensure_map_slot(id);
        }

        let mut draws = Vec::with_capacity(self.entities.len());
        let mut items = Vec::new();
        let mut hand_items: Vec<HandItem> = Vec::new();
        let mut item_frames: Vec<ItemFrameDraw> = Vec::new();
        for entity in &self.entities {
            let x = entity.prev[0] + (entity.position[0] - entity.prev[0]) * alpha;
            let y = entity.prev[1] + (entity.position[1] - entity.prev[1]) * alpha;
            let z = entity.prev[2] + (entity.position[2] - entity.prev[2]) * alpha;

            if let Some((item, meta)) = entity.item {
                items.push(ItemDraw {
                    position: [x as f32, y as f32, z as f32],
                    item,
                    meta,
                });
                continue;
            }

            if let Some((direction, rotation, framed)) = entity.item_frame {
                let map_id = framed.and_then(|item| map_id_of(&item));
                let (item_slot, item_tint) = match map_id {
                    Some(id) => (self.map_slots.get(&id).copied(), [1.0; 4]),
                    None => (
                        None,
                        framed
                            .map(|item| frame_item_tint(item.id))
                            .unwrap_or([1.0; 4]),
                    ),
                };
                item_frames.push(ItemFrameDraw {
                    position: [x as f32, y as f32, z as f32],
                    direction,
                    rotation,
                    frame_slot: self.item_frame_slot,
                    item_slot,
                    item_tint,
                });
                continue;
            }

            let yaw = lerp_degrees(entity.prev_yaw, entity.yaw, alpha);
            let head_yaw = lerp_degrees(entity.prev_head_yaw, entity.head_yaw, alpha);
            let mut draw = if entity.player {
                let slot = self
                    .skin_slots
                    .get(&entity.uuid)
                    .copied()
                    .unwrap_or(SkinAtlas::DEFAULT_SLOT);
                EntityDraw::player(
                    [x as f32, y as f32, z as f32],
                    yaw,
                    head_yaw,
                    entity.pitch,
                    slot,
                )
            } else {
                let slot = self
                    .mob_slots
                    .get(&entity.kind)
                    .copied()
                    .unwrap_or(SkinAtlas::DEFAULT_SLOT);
                let speed = (entity.velocity[0] * entity.velocity[0]
                    + entity.velocity[2] * entity.velocity[2])
                    .sqrt();
                let mut walk = if speed > 0.005 {
                    self.time * 7.0 + entity.id as f32 * 0.37
                } else {
                    0.0
                };
                if entity.animation != 0 && entity.animation_ticks > 0 {
                    walk += 0.7;
                }
                let mut draw = EntityDraw::mob(
                    [x as f32, y as f32, z as f32],
                    yaw,
                    head_yaw,
                    entity.pitch,
                    slot,
                    entity.kind,
                    walk,
                );
                draw.tint = if self.mob_slots.contains_key(&entity.kind) {
                    [1.0; 4]
                } else {
                    mob_tint(entity.kind)
                };
                draw.scale = mob_scale(entity.kind);
                draw
            };
            if entity.player {
                let speed = (entity.velocity[0] * entity.velocity[0]
                    + entity.velocity[2] * entity.velocity[2])
                    .sqrt();
                if speed > 0.005 {
                    draw.walk = self.time * 7.0 + entity.id as f32 * 0.37;
                }
            }
            draw.invisible = entity.flags & 0x20 != 0;
            draw.crouch = entity.flags & 0x02 != 0;
            draw.slim = entity.player && self.skin_slim.get(&entity.uuid).copied().unwrap_or(false);
            draw.arm_swing = if entity.animation == 0 && entity.animation_ticks > 0 {
                (8 - entity.animation_ticks) as f32 / 8.0
            } else {
                0.0
            };
            draw.armor = entity
                .armor
                .map(|item| item.and_then(|item| armor_tint(item.id)));

            if let Some(held) = entity.held_item {
                if let Some(id) = map_id_of(&held) {
                    draw.held_map_slot = self.map_slots.get(&id).copied();
                } else {
                    let pose = humanoid_hand(&draw);
                    let (item, meta) = held
                        .block_state()
                        .map(|raw| {
                            let state = nephele_world::BlockState::from_raw(raw);
                            (state.id() as i16, state.meta() as i16)
                        })
                        .unwrap_or((held.id, held.damage));
                    hand_items.push(HandItem {
                        item,
                        meta,
                        centre: [
                            pose.palm[0] + pose.forward[0] * 0.12,
                            pose.palm[1] + pose.forward[1] * 0.12,
                            pose.palm[2] + pose.forward[2] * 0.12,
                        ],
                        right: pose.right,
                        up: pose.up,
                        forward: pose.forward,
                        size: 0.36,
                    });
                }
            }
            draws.push(draw);
        }

        let mut entity_mesh = build_entities(&draws);
        for frame in &item_frames {
            append_item_frame(&mut entity_mesh, frame);
        }
        for block in &self.block_entities {
            let (model, slot, tint) = match &block.kind {
                BlockEntityKind::Sign { .. } => (BlockEntityModel::Sign, self.sign_slot, [1.0; 4]),
                BlockEntityKind::Chest => (BlockEntityModel::Chest, self.chest_slot, [1.0; 4]),
                BlockEntityKind::Banner { base, .. } => (
                    BlockEntityModel::Banner,
                    self.banner_slot,
                    banner_tint(*base),
                ),
                BlockEntityKind::Beacon { levels, .. } if *levels > 0 => (
                    BlockEntityModel::BeaconBeam,
                    self.beacon_beam_slot,
                    [1.0, 0.95, 0.65, 1.0],
                ),
                BlockEntityKind::EnchantingTable => {
                    (BlockEntityModel::EnchantingBook, self.book_slot, [1.0; 4])
                }
                _ => continue,
            };
            append_block_entity(
                &mut entity_mesh,
                &BlockEntityDraw {
                    position: [block.x as f32, block.y as f32, block.z as f32],
                    model,
                    slot,
                    tint,
                    yaw: 0.0,
                    phase: self.time,
                },
            );
        }

        let mut item_mesh = build_item_mesh(&items, &textures, self.time);
        for hand in &hand_items {
            if (1..256).contains(&hand.item) {
                item_mesh.append(build_hand_item(hand, &textures));
            } else {
                item_mesh.append(build_hand_sprite(hand, &textures));
            }
        }
        if self.screen == Screen::Game {
            // The first-person arm is built in camera space and placed in the
            // world, so it lands in the same depth-tested pass as everything else.
            let camera = &view.camera;
            let swing = if view.attacking {
                (self.time * 11.0).sin() * 0.5 + 0.5
            } else {
                0.0
            };
            let pose = append_hand(
                &mut entity_mesh,
                &HandDraw {
                    eye: camera.position.to_array(),
                    right: camera.right().to_array(),
                    up: camera.up().to_array(),
                    forward: camera.forward().to_array(),
                    skin_slot: SkinAtlas::DEFAULT_SLOT,
                    swing,
                },
            );

            let held = view
                .inventory
                .get(play::HOTBAR_FIRST_SLOT + view.held_slot.max(0) as usize)
                .copied()
                .flatten();
            if let Some(held) = held {
                if let Some(id) = map_id_of(&held) {
                    if let Some(slot) = self.map_slots.get(&id).copied() {
                        append_hand_map(&mut entity_mesh, &pose, slot, 0.35);
                    }
                } else if let Some(state) = held.block_state() {
                    let state = nephele_world::BlockState::from_raw(state);
                    item_mesh.append(build_hand_item(
                        &HandItem {
                            item: state.id() as i16,
                            meta: state.meta() as i16,
                            centre: pose.palm,
                            right: pose.right,
                            up: pose.up,
                            forward: pose.forward,
                            size: 0.36,
                        },
                        &textures,
                    ));
                } else {
                    item_mesh.append(build_hand_sprite(
                        &HandItem {
                            item: held.id,
                            meta: held.damage,
                            centre: pose.palm,
                            right: pose.right,
                            up: pose.up,
                            forward: pose.forward,
                            size: 0.35,
                        },
                        &textures,
                    ));
                }
            }
        }
        item_mesh.append(build_particle_mesh(
            &self.particles.draws(),
            &textures,
            view.camera.right().to_array(),
            view.camera.up().to_array(),
        ));
        if let Some(renderer) = self.renderer.as_mut() {
            renderer.set_entities(&entity_mesh);
            renderer.set_items(&item_mesh);
        }
    }

    fn drain_network(&mut self) {
        loop {
            match self.rx.try_recv() {
                Ok(NetMsg::Chunks(columns)) => {
                    for column in columns {
                        let key = (column.x, column.z);
                        self.world.insert(column);
                        self.mark_dirty(key);
                        // A new column changes what its neighbours' border faces
                        // must cull, so they need re-meshing too.
                        self.mark_neighbours_dirty(key);
                    }
                }
                Ok(NetMsg::Unload(x, z)) => {
                    self.world.remove(ChunkCoord::new(x, z));
                    self.queued.remove(&(x, z));
                    self.stale.remove(&(x, z));
                    if let Some(renderer) = self.renderer.as_mut() {
                        renderer.remove_chunk((x, z));
                    }
                    self.mark_neighbours_dirty((x, z));
                }
                Ok(NetMsg::Chat(text)) => {
                    println!("[chat] {text}");
                    self.push_chat(text);
                }
                Ok(NetMsg::Entities(snapshot)) => {
                    self.entities = snapshot;
                }
                Ok(NetMsg::BlockEntities(snapshot)) => {
                    self.block_entities = snapshot;
                }
                Ok(NetMsg::Particles(particles)) => {
                    for particle in particles {
                        self.particles.spawn_event(&particle);
                    }
                }
                Ok(NetMsg::Sound(sound)) => {
                    if let Some(audio) = &self.audio {
                        audio.play(
                            &sound.name,
                            Some([sound.x as f32, sound.y as f32, sound.z as f32]),
                            sound.volume,
                            sound.pitch,
                        );
                    }
                }
                Ok(NetMsg::Skins(skins)) => {
                    for (uuid, hash, slim) in skins {
                        self.skin_slim.insert(uuid, slim);
                        // Reserve a slot on first sight and start the download.
                        self.skin_slots.entry(uuid).or_insert_with(|| {
                            self.skin_loader.request(&hash);
                            self.skin_atlas.assign(&hash)
                        });
                    }
                }
                Ok(NetMsg::Map(id, state)) => {
                    self.maps.insert(id, state);
                    let slot = self.ensure_map_slot(id);
                    self.upload_map(id, slot);
                }
                Ok(NetMsg::Error(err)) => {
                    eprintln!("network error: {err}");
                    let mut state = self.shared.lock().unwrap();
                    state.error = Some(err);
                }
                Err(TryRecvError::Empty) => return,
                Err(TryRecvError::Disconnected) => return,
            }
        }
    }

    fn push_input(&mut self) {
        let mut input = Input::default();
        if self.keys.contains(&KeyCode::KeyW) {
            input.forward += 1.0;
        }
        if self.keys.contains(&KeyCode::KeyS) {
            input.forward -= 1.0;
        }
        if self.keys.contains(&KeyCode::KeyD) {
            input.strafe += 1.0;
        }
        if self.keys.contains(&KeyCode::KeyA) {
            input.strafe -= 1.0;
        }
        input.jump = self.keys.contains(&KeyCode::Space);
        input.sneak =
            self.keys.contains(&KeyCode::ShiftLeft) || self.keys.contains(&KeyCode::ShiftRight);
        input.sprint = self.keys.contains(&KeyCode::ControlLeft);

        let mut state = self.shared.lock().unwrap();
        state.input = input;
    }

    /// Rebuild the selection outline and the crack overlay when they move.
    fn update_highlights(&mut self, aim: Option<Aim>, stage: Option<u8>) {
        if aim != self.drawn_aim {
            self.drawn_aim = aim;
            let lines = match aim {
                Some(aim) => block_outline(aim.x, aim.y, aim.z, OUTLINE_COLOR),
                None => LineMesh::default(),
            };
            if let Some(renderer) = self.renderer.as_mut() {
                renderer.set_lines(&lines);
            }
        }

        if stage != self.drawn_stage || (stage.is_some() && aim != self.drawn_aim) {
            self.drawn_stage = stage;
            let overlay = match (aim, stage, self.textures.as_ref()) {
                (Some(aim), Some(stage), Some(textures)) => {
                    let layer = textures.layer_or_missing(break_overlay_texture(stage));
                    build_break_overlay(aim.x, aim.y, aim.z, layer)
                }
                _ => MeshData::default(),
            };
            if let Some(renderer) = self.renderer.as_mut() {
                renderer.set_overlay(&overlay);
            }
        }
    }

    fn frame(&mut self) {
        if self.renderer.is_none() {
            return;
        }
        let Some(window) = self.window.clone() else {
            return;
        };

        let now = Instant::now();
        let frame_interval = now.saturating_duration_since(self.last_frame);
        self.last_frame = now;
        perf::record_frame_interval(frame_interval);
        let delta = frame_interval.as_secs_f32().min(0.1);

        self.drain_network();
        self.drain_pings();
        self.push_input();

        let view = {
            let mut state = self.shared.lock().unwrap();
            // Physics runs at 20 Hz; render between ticks so motion is smooth
            // instead of stepping, like vanilla's `lastTickPos` interpolation.
            let alpha = ((Instant::now() - state.tick_at).as_secs_f64() / TICK.as_secs_f64())
                .clamp(0.0, 1.0);
            let prev = state.prev_position;
            let current = [state.player.x, state.player.y, state.player.z];
            let feet = [
                prev[0] + (current[0] - prev[0]) * alpha,
                prev[1] + (current[1] - prev[1]) * alpha,
                prev[2] + (current[2] - prev[2]) * alpha,
            ];
            FrameView {
                camera: Camera {
                    position: glam::Vec3::new(
                        feet[0] as f32,
                        (feet[1] + EYE_HEIGHT) as f32,
                        feet[2] as f32,
                    ),
                    yaw: state.yaw,
                    pitch: state.pitch,
                    fov_y: self.settings.fov.to_radians(),
                    ..Camera::default()
                },
                status: state.status.clone(),
                error: state.error.take(),
                aim: state.aim,
                stage: state.break_stage,
                held_slot: state.held_slot,
                creative: state.creative,
                attacking: state.attacking,
                inventory_cursor: if state.local && state.window_id == Some(1) {
                    state.local_container.cursor()
                } else {
                    self.inventory_cursor
                },
                inventory: state.inventory.clone(),
                window_open: state.window_open,
                window_slots: state.window_slots.clone(),
                health: state.health,
                food: state.food,
                xp_bar: state.xp_bar,
                xp_level: state.xp_level,
                chunks: state.chunks,
                feet,
                alpha,
                time_of_day: state.time_of_day,
            }
        };

        if let Some(err) = &view.error {
            eprintln!("disconnected: {err}");
        }
        if let Some(audio) = &self.audio {
            audio.set_listener(view.camera.position.to_array(), view.camera.yaw);
        }

        // Right-clicking a crafting table opens a server window; show it.
        if view.window_open && self.screen == Screen::Game {
            self.screen = Screen::Inventory;
            self.inventory_cursor = None;
            self.set_mouse_capture(false);
        }

        // Collect finished meshes and upload them. This is the only chunk work
        // the render thread does, so streaming a view distance never stalls it.
        let mesh_start = Instant::now();
        let mut finished = Vec::new();
        if let Some(pool) = self.mesh_pool.as_mut() {
            while let Some(item) = pool.try_recv() {
                finished.push(item);
            }
        }
        for (key, mesh) in finished {
            self.queued.remove(&key);
            if self.stale.remove(&key) {
                // Edited while it was being meshed: rebuild from current data.
                if self.queued.insert(key) {
                    self.dirty_chunks.push(key);
                }
                continue;
            }
            self.upload_chunk(key, &mesh);
        }

        // Then hand the nearest pending columns to the workers.
        if !self.dirty_chunks.is_empty() {
            let eye_x = view.camera.position.x;
            let eye_z = view.camera.position.z;
            let distance = |key: &(i32, i32)| {
                let dx = key.0 as f32 * 16.0 + 8.0 - eye_x;
                let dz = key.1 as f32 * 16.0 + 8.0 - eye_z;
                dx * dx + dz * dz
            };
            // Sorted farâ†’near so `pop()` yields the closest column.
            self.dirty_chunks
                .sort_unstable_by(|a, b| distance(b).total_cmp(&distance(a)));

            let free = self
                .mesh_pool
                .as_ref()
                .map(|pool| pool.capacity().saturating_sub(pool.in_flight()))
                .unwrap_or(0);
            let mut jobs = Vec::with_capacity(free);
            while jobs.len() < free {
                let Some(key) = self.dirty_chunks.pop() else {
                    break;
                };
                if !self.world.contains(ChunkCoord::new(key.0, key.1)) {
                    self.queued.remove(&key);
                    continue;
                }
                jobs.push(ColumnMeshJob::from_world(key, &self.world));
            }
            if let Some(pool) = self.mesh_pool.as_mut() {
                for job in jobs {
                    if !pool.submit(job) {
                        break;
                    }
                }
            }
        }
        self.prof_mesh += mesh_start.elapsed().as_secs_f32() * 1000.0;

        self.update_skins();
        self.particles.update(delta);
        if self.screen == Screen::Game {
            self.particles.ambient_tick(
                delta,
                view.feet.map(|value| value as f32),
                is_night(view.time_of_day),
            );
        }
        self.draw_entities(&view);
        if let Some(renderer) = self.renderer.as_mut() {
            renderer.set_sky_color(sky_color(view.time_of_day));
            renderer.set_world_light(world_light(view.time_of_day));
        }

        self.time += delta;
        let ui_start = Instant::now();
        self.update_highlights(view.aim, view.stage);
        self.draw_ui(&view);
        self.prof_ui += ui_start.elapsed().as_secs_f32() * 1000.0;

        // The title screen orbits a camera inside the panorama cube.
        let mut camera = view.camera.clone();
        let size = window.inner_size();
        if size.height > 0 {
            camera.set_aspect(size.width, size.height);
        }
        let title = self.screen == Screen::Title;
        if title {
            camera = Camera {
                position: glam::Vec3::ZERO,
                yaw: self.time * 0.02,
                pitch: 0.0,
                fov_y: 70f32.to_radians(),
                ..camera
            };
        }

        let mut presented = false;
        let first_frame = self.prof_frames == 0;
        let draw_start = Instant::now();
        if let Some(renderer) = self.renderer.as_mut() {
            renderer.set_panorama(title);
            match renderer.draw(&camera) {
                nephele_render::DrawOutcome::Presented => presented = true,
                // Occluded windows can't be acquired; don't spin at 1000 Hz
                // burning CPU, and don't count those as frames.
                _ => std::thread::sleep(Duration::from_millis(8)),
            }
        }
        if first_frame {
            perf::record_stage_span("first_frame_pipeline_creation", draw_start, Instant::now());
        }
        self.prof_draw += draw_start.elapsed().as_secs_f32() * 1000.0;

        if presented {
            self.frames += 1;
        }
        self.prof_frames += 1;
        self.title_timer += delta;
        if self.title_timer >= 0.4 {
            let fps = self.frames as f32 / self.title_timer;
            self.last_fps = fps;
            let target = match view.aim {
                Some(aim) => format!(
                    "{} {} {} {}",
                    aim.x,
                    aim.y,
                    aim.z,
                    nephele_world::Face::from_protocol_id(aim.face)
                        .map(|face| face.name())
                        .unwrap_or("?")
                ),
                None => "-".to_string(),
            };
            if self.profile {
                let frames = self.prof_frames.max(1) as f32;
                let (drawn, total) = self
                    .renderer
                    .as_ref()
                    .map(Renderer::draw_stats)
                    .unwrap_or((0, 0));
                println!(
                    "[frame] {:5.2} ms  ui {:5.2}  mesh {:5.2}  draw {:5.2}  \
                     drawcalls {}/{}  pending {}  meshq {}  ents {}  entidx {}",
                    self.title_timer * 1000.0 / frames,
                    self.prof_ui / frames,
                    self.prof_mesh / frames,
                    self.prof_draw / frames,
                    drawn,
                    total,
                    self.dirty_chunks.len(),
                    self.mesh_pool
                        .as_ref()
                        .map(|pool| pool.in_flight())
                        .unwrap_or(0),
                    self.entities.len(),
                    self.renderer
                        .as_ref()
                        .map(Renderer::entity_index_count)
                        .unwrap_or(0),
                );
                self.prof_ui = 0.0;
                self.prof_mesh = 0.0;
                self.prof_draw = 0.0;
                self.prof_frames = 0;
            }
            window.set_title(&format!(
                "Nephele{} - {} - {:.0} fps - {:.1} {:.1} {:.1} - look {:.0}/{:.0} - slot {} - {}",
                if view.creative { " [creative]" } else { "" },
                view.status,
                fps,
                view.camera.position.x,
                view.camera.position.y,
                view.camera.position.z,
                view.camera.yaw.to_degrees(),
                view.camera.pitch.to_degrees(),
                view.held_slot,
                target
            ));
            self.title_timer = 0.0;
            self.frames = 0;
        }
    }

    /// Build and upload this frame's HUD / menu geometry.
    fn draw_ui(&mut self, view: &FrameView) {
        let Some(window) = self.window.as_ref() else {
            return;
        };
        let size = window.inner_size();
        let (width, height) = (size.width as f32, size.height as f32);
        let scale = if self.settings.gui_scale == 0 {
            ui::gui_scale(width, height)
        } else {
            self.settings.gui_scale as f32
        };

        self.ui_bg.clear();
        self.ui_icons.clear();
        self.ui_fg.clear();

        let hud = HudState {
            inventory: &view.inventory,
            held_slot: view.held_slot,
            health: view.health,
            food: view.food,
            xp_bar: view.xp_bar,
            xp_level: view.xp_level,
            fps: self.last_fps,
            position: view.feet,
            chunks: view.chunks,
            creative: view.creative,
            creative_page: self.creative_page,
            pointer: self.pointer,
            captured: self.mouse_captured,
            chatting: self.chat_open,
            window_slots: if view.window_open {
                Some(view.window_slots.as_slice())
            } else {
                None
            },
        };

        self.buttons = match self.screen {
            Screen::Title => ui::draw_title(
                &mut self.ui_bg,
                &mut self.ui_fg,
                &self.splash,
                self.time,
                self.pointer,
                scale,
                width,
                height,
            ),
            Screen::Worlds => ui::draw_worlds(
                &mut self.ui_bg,
                &mut self.ui_fg,
                &self.worlds,
                self.worlds_scroll,
                self.world_error.as_deref(),
                self.pointer,
                scale,
                width,
                height,
            ),
            Screen::WorldCreate => ui::draw_world_create(
                &mut self.ui_bg,
                &mut self.ui_fg,
                &self.world_name_input,
                &self.world_seed_input,
                self.world_create_mode,
                self.world_name_focused,
                self.world_seed_focused,
                self.world_error.as_deref(),
                self.pointer,
                scale,
                width,
                height,
            ),
            Screen::Servers => ui::draw_servers(
                &mut self.ui_bg,
                &mut self.ui_fg,
                &self.servers,
                &self.pings,
                self.servers_selected.as_deref(),
                self.servers_scroll,
                self.pointer,
                scale,
                width,
                height,
            ),
            Screen::Connect => ui::draw_connect(
                &mut self.ui_bg,
                &mut self.ui_fg,
                &self.address_input,
                self.pointer,
                scale,
                width,
                height,
            ),
            Screen::Game if hud.health <= 0.0 => {
                self.screen = Screen::Death;
                ui::draw_death(
                    &mut self.ui_bg,
                    &mut self.ui_fg,
                    hud.pointer,
                    scale,
                    width,
                    height,
                )
            }
            Screen::Game => {
                let Some(textures) = self.textures.as_ref() else {
                    return;
                };
                ui::draw_hud(
                    &mut self.ui_bg,
                    &mut self.ui_fg,
                    &mut self.ui_icons,
                    &hud,
                    textures,
                    scale,
                    width,
                    height,
                )
            }
            Screen::Death => ui::draw_death(
                &mut self.ui_bg,
                &mut self.ui_fg,
                hud.pointer,
                scale,
                width,
                height,
            ),
            Screen::Pause => {
                ui::draw_pause(&mut self.ui_bg, &mut self.ui_fg, &hud, scale, width, height)
            }
            Screen::Settings => ui::draw_settings(
                &mut self.ui_bg,
                &mut self.ui_fg,
                &hud,
                &self.settings,
                scale,
                width,
                height,
            ),
            Screen::Creative => {
                let Some(textures) = self.textures.as_ref() else {
                    return;
                };
                ui::draw_creative(
                    &mut self.ui_bg,
                    &mut self.ui_fg,
                    &mut self.ui_icons,
                    &hud,
                    textures,
                    scale,
                    width,
                    height,
                )
            }
            Screen::Inventory => {
                let Some(textures) = self.textures.as_ref() else {
                    return;
                };
                ui::draw_inventory(
                    &mut self.ui_bg,
                    &mut self.ui_fg,
                    &mut self.ui_icons,
                    &hud,
                    view.inventory_cursor,
                    textures,
                    scale,
                    width,
                    height,
                )
            }
        };

        if self.screen == Screen::Game {
            self.draw_chat(scale, width, height);
            self.draw_entity_labels(view, scale, width, height);
        }

        if let Some(renderer) = self.renderer.as_mut() {
            renderer.set_ui(&self.ui_bg, &self.ui_icons, &self.ui_fg);
        }
    }

    /// Project living entities' display names and health above their heads.
    fn draw_entity_labels(&mut self, view: &FrameView, scale: f32, width: f32, height: f32) {
        let matrix = view.camera.view_projection();
        for entity in &self.entities {
            if entity.item.is_some() || entity.item_frame.is_some() || entity.flags & 0x20 != 0 {
                continue;
            }
            let x = entity.position[0] as f32;
            let y = entity.position[1] as f32 + if entity.player { 2.05 } else { 1.75 };
            let z = entity.position[2] as f32;
            let clip = matrix * glam::Vec4::new(x, y, z, 1.0);
            if clip.w <= 0.1 {
                continue;
            }
            let ndc = clip.truncate() / clip.w;
            if ndc.x.abs() > 1.0 || ndc.y.abs() > 1.0 {
                continue;
            }
            let screen_x = (ndc.x * 0.5 + 0.5) * width;
            let screen_y = (1.0 - (ndc.y * 0.5 + 0.5)) * height;
            let distance = view.camera.position.distance(glam::Vec3::new(x, y, z));
            // Vanilla keeps the tag readable at range instead of letting it
            // shrink into the background. 14 blocks is roughly the point where
            // a 0.025-scale tag reaches one GUI pixel per texel.
            let local_scale = scale * (14.0 / distance.max(1.0)).clamp(0.55, 1.5);
            let label = if entity.show_name && !entity.name.is_empty() {
                if entity.player {
                    entity.name.clone()
                } else {
                    format!("{}\n{} HP", entity.name, entity.health.ceil() as i32)
                }
            } else if !entity.player {
                format!("{} HP", entity.health.ceil() as i32)
            } else {
                continue;
            };
            let lines = label.lines().count().max(1) as f32;
            let text_width = UiBatch::text_width(&label, local_scale);
            let line_height = 9.0 * local_scale;
            let padding = 2.0 * local_scale;
            self.ui_bg.rect(
                Rect::new(
                    screen_x - text_width / 2.0 - padding,
                    screen_y - padding * 0.5,
                    text_width + padding * 2.0,
                    lines * line_height + padding,
                ),
                [0.0, 0.0, 0.0, 0.45],
            );
            self.ui_fg
                .text_centered(&label, screen_x, screen_y, local_scale, [1.0; 4]);
        }

        for block in &self.block_entities {
            let BlockEntityKind::Sign { lines, .. } = &block.kind else {
                continue;
            };
            if lines.iter().all(String::is_empty) {
                continue;
            }
            let x = block.x as f32 + 0.5;
            let y = block.y as f32 + 1.25;
            let z = block.z as f32 + 0.5;
            let clip = matrix * glam::Vec4::new(x, y, z, 1.0);
            if clip.w <= 0.1 {
                continue;
            }
            let ndc = clip.truncate() / clip.w;
            if ndc.x.abs() > 1.0 || ndc.y.abs() > 1.0 {
                continue;
            }
            let screen_x = (ndc.x * 0.5 + 0.5) * width;
            let screen_y = (1.0 - (ndc.y * 0.5 + 0.5)) * height;
            let label = lines
                .iter()
                .filter(|line| !line.is_empty())
                .cloned()
                .collect::<Vec<_>>()
                .join("\n");
            self.ui_fg.text_centered(
                &label,
                screen_x,
                screen_y,
                scale * 0.8,
                [0.1, 0.1, 0.1, 1.0],
            );
        }
    }

    /// Apply a look delta, in raw device pixels.
    fn look(&mut self, dx: f32, dy: f32) {
        let mut state = self.shared.lock().unwrap();
        let dx = dx * self.settings.sensitivity;
        let dy = dy * self.settings.sensitivity;
        state.yaw = (state.yaw + dx * MOUSE_SENSITIVITY) % std::f32::consts::TAU;
        let limit = 89f32.to_radians();
        state.pitch = (state.pitch - dy * MOUSE_SENSITIVITY).clamp(-limit, limit);
    }

    /// Spawn the network thread for `address` and switch to the game screen.
    fn start_network(&mut self, address: ServerAddress) {
        self.screen = Screen::Game;
        self.set_mouse_capture(false);
        let shared = Arc::clone(&self.shared);
        let username = self.options.username.clone();
        let session_path = if self.options.online {
            Some(self.options.session_path.clone())
        } else {
            None
        };
        let tx = self.tx.clone();
        let error_tx = tx.clone();
        let _ = std::thread::Builder::new()
            .name("nephele-net".into())
            .spawn(move || {
                let runtime = match tokio::runtime::Builder::new_current_thread()
                    .enable_all()
                    .build()
                {
                    Ok(runtime) => runtime,
                    Err(err) => {
                        let _ = error_tx.send(NetMsg::Error(err.to_string()));
                        return;
                    }
                };
                if let Err(err) =
                    runtime.block_on(net_loop(address, username, session_path, shared, tx))
                {
                    let _ = error_tx.send(NetMsg::Error(err));
                }
            });
    }

    fn refresh_worlds(&mut self) {
        match save::list_worlds(&self.saves_dir) {
            Ok(worlds) => {
                self.worlds = worlds;
                self.worlds_scroll = self.worlds_scroll.min(self.worlds_max_scroll());
                self.world_error = None;
            }
            Err(error) => {
                self.worlds.clear();
                self.world_error = Some(error.to_string());
            }
        }
    }

    fn worlds_max_scroll(&self) -> usize {
        self.worlds.len().saturating_sub(ui::WORLD_ROWS)
    }

    fn scroll_worlds(&mut self, steps: i32) {
        let next = self.worlds_scroll as i32 - steps;
        self.worlds_scroll = next.clamp(0, self.worlds_max_scroll() as i32) as usize;
    }

    fn open_worlds(&mut self) {
        self.set_mouse_capture(false);
        self.world_error = None;
        self.worlds_scroll = 0;
        self.screen = Screen::Worlds;
        self.refresh_worlds();
    }

    fn open_world_create(&mut self) {
        self.world_name_input.clear();
        self.world_seed_input = self
            .options
            .seed
            .map(|seed| seed.to_string())
            .unwrap_or_default();
        self.world_create_mode = WorldMode::Creative;
        self.world_name_focused = true;
        self.world_seed_focused = false;
        self.world_error = None;
        self.screen = Screen::WorldCreate;
    }

    fn create_local_world(&mut self) {
        let seed = if self.world_seed_input.trim().is_empty() {
            fresh_world_seed()
        } else {
            match self.world_seed_input.trim().parse::<u64>() {
                Ok(seed) => seed,
                Err(_) => {
                    self.world_error = Some("Seed must be an unsigned integer".to_string());
                    return;
                }
            }
        };
        match WorldSave::create(
            &self.saves_dir,
            &self.world_name_input,
            seed,
            self.world_create_mode,
        ) {
            Ok(save) => {
                self.world_error = None;
                self.refresh_worlds();
                self.start_local_save(save);
            }
            Err(error) => self.world_error = Some(error.to_string()),
        }
    }

    fn open_saved_world(&mut self, index: usize) {
        let Some(world) = self.worlds.get(index) else {
            return;
        };
        match WorldSave::open(&self.saves_dir, &world.directory) {
            Ok(save) => self.start_local_save(save),
            Err(error) => {
                let message = error.to_string();
                self.refresh_worlds();
                self.world_error = Some(message);
            }
        }
    }

    /// Development shortcut: open (or create) the default persistent world.
    fn start_local(&mut self) {
        let seed = self.options.seed.unwrap_or_else(fresh_world_seed);
        let existing = save::list_worlds(&self.saves_dir)
            .ok()
            .and_then(|worlds| worlds.into_iter().find(|world| world.directory == "World"));
        let world = match existing {
            Some(world) => WorldSave::open(&self.saves_dir, &world.directory),
            None => WorldSave::create(&self.saves_dir, "World", seed, WorldMode::Creative),
        };
        match world {
            Ok(save) => self.start_local_save(save),
            Err(error) => {
                self.world_error = Some(error.to_string());
                self.screen = Screen::Title;
            }
        }
    }

    fn start_local_save(&mut self, save: WorldSave) {
        let mode = save.metadata().mode;
        self.screen = Screen::Game;
        self.set_mouse_capture(false);
        {
            let mut state = self.shared.lock().unwrap();
            state.creative = mode.is_creative();
            state.local = true;
            state.time_of_day = std::env::var("NEPHELE_TIME")
                .ok()
                .and_then(|value| value.parse::<i64>().ok())
                .unwrap_or(6_000)
                .rem_euclid(24_000);
            state.time_override = None;
        }
        let shared = Arc::clone(&self.shared);
        let tx = self.tx.clone();
        let _ = std::thread::Builder::new()
            .name("nephele-local".into())
            .spawn(move || {
                if let Err(err) = local_loop(save, shared, tx.clone()) {
                    let _ = tx.send(NetMsg::Error(err));
                }
            });
    }

    /// Parse the typed address and connect, or report it on the screen.
    ///
    /// A successful join is also what remembers the server: the list is a
    /// history of everywhere you have played.
    fn connect_from_input(&mut self) {
        let text = self.address_input.trim().to_string();
        if text.is_empty() {
            return;
        }
        match ServerAddress::parse(&text) {
            Ok(address) => {
                self.address_input.clear();
                self.remember_server(&text);
                self.start_network(address);
            }
            Err(err) => {
                self.shared.lock().unwrap().status = format!("bad address: {err}");
            }
        }
    }

    /// Add `address` to the saved list and write it back to disk.
    fn remember_server(&mut self, address: &str) {
        self.servers.add(ServerEntry::new("", address));
        self.save_servers();
    }

    /// Ping every saved server whose state is not already in flight.
    ///
    /// Called when the screen opens and by the Refresh button â€” there is no
    /// polling loop. Each server gets its own short-lived thread, the same shape
    /// vanilla uses; a saved list is small, and one slow host must not hold up
    /// the rest.
    fn refresh_server_list(&mut self) {
        let addresses: Vec<String> = self
            .servers
            .entries()
            .iter()
            .map(|entry| entry.address.clone())
            .collect();
        for address in addresses {
            if !self.pings.begin(&address) {
                continue;
            }
            let tx = self.ping_tx.clone();
            let _ = std::thread::Builder::new()
                .name("nephele-ping".into())
                .spawn(move || {
                    let ping = ping_server(&address);
                    let _ = tx.send(PingReply { address, ping });
                });
        }
    }

    fn drain_pings(&mut self) {
        while let Ok(reply) = self.ping_rx.try_recv() {
            self.pings.finish(&reply.address, reply.ping);
        }
    }

    /// The Multiplayer button: show the list and ask every row how it is.
    fn open_servers(&mut self) {
        self.screen = Screen::Servers;
        self.servers_scroll = 0;
        self.servers_selected = None;
        self.refresh_server_list();
    }

    /// Open the chat line. `/` prefills the slash so commands are one key away.
    fn open_chat(&mut self, prefill_slash: bool) {
        self.chat_open = true;
        self.chat_input.clear();
        if prefill_slash {
            self.chat_input.push('/');
        }
        self.keys.clear();
        self.set_mouse_capture(false);
    }

    fn push_chat(&mut self, text: impl Into<String>) {
        self.chat_log.push_back(ChatLine {
            text: text.into(),
            at: Instant::now(),
        });
        while self.chat_log.len() > 100 {
            self.chat_log.pop_front();
        }
    }

    /// Enter: run it if it is one of ours, otherwise send it to the server.
    fn send_chat_line(&mut self) {
        let line = std::mem::take(&mut self.chat_input);
        self.chat_open = false;
        self.enter_game();
        if line.trim().is_empty() {
            return;
        }
        match line.strip_prefix('/') {
            Some(command) => self.run_command(command),
            None => self.shared.lock().unwrap().chat_out.push(line),
        }
    }

    fn run_command(&mut self, line: &str) {
        let position = {
            let state = self.shared.lock().unwrap();
            [state.player.x, state.player.y, state.player.z]
        };
        match commands::parse(line, position) {
            // A command we do not implement goes to the server unchanged, the
            // way vanilla's client forwards everything and lets the server
            // decide whether the player may run it.
            commands::Parsed::Unknown => {
                self.shared
                    .lock()
                    .unwrap()
                    .chat_out
                    .push(format!("/{line}"));
            }
            commands::Parsed::Error(message) => self.push_chat(message),
            commands::Parsed::Command(command) => self.apply_command(command),
        }
    }

    fn apply_command(&mut self, command: commands::Command) {
        use commands::{Command, GameMode};
        match command {
            Command::Help => {
                for line in commands::help_lines() {
                    self.push_chat(line);
                }
            }
            Command::Seed => {
                let seed = self.options.seed.unwrap_or(0);
                self.push_chat(format!("Seed: {seed}"));
            }
            Command::Gamemode(mode) => {
                let creative = mode == GameMode::Creative;
                self.shared.lock().unwrap().creative_override = Some(creative);
                self.push_chat(if creative {
                    "Game mode set to creative"
                } else {
                    "Game mode set to survival"
                });
            }
            Command::Teleport { x, y, z } => {
                self.shared.lock().unwrap().teleport = Some([x, y, z]);
                self.push_chat(format!("Teleported to {x:.1} {y:.1} {z:.1}"));
            }
            Command::SetBlock { x, y, z, id, meta } => {
                let state = nephele_world::BlockState::new(id, meta).raw();
                self.shared
                    .lock()
                    .unwrap()
                    .world_edits
                    .push((x, y, z, state));
                self.push_chat(format!(
                    "Set {x} {y} {z} to {}",
                    nephele_world::blocks::name(id)
                ));
            }
            Command::Time(time) => {
                self.shared.lock().unwrap().time_override = Some(time);
                self.push_chat(format!("Time set to {time}"));
            }
            Command::Give { id, meta, count } => {
                let slot =
                    play::HOTBAR_FIRST_SLOT as i16 + self.shared.lock().unwrap().held_slot.max(0);
                let item = ItemStack::new(id as i16, count, meta as i16);
                self.shared.lock().unwrap().give_item = Some((slot, item));
                self.push_chat(format!(
                    "Gave {count} x {}",
                    nephele_world::blocks::name(id)
                ));
            }
        }
    }

    /// Recent chat and, while it is open, the input line.
    fn draw_chat(&mut self, scale: f32, width: f32, height: f32) {
        let now = Instant::now();
        self.chat_log
            .retain(|line| now.duration_since(line.at).as_secs_f32() < 14.0);
        let lines: Vec<(String, f32)> = self
            .chat_log
            .iter()
            .rev()
            .take(10)
            .rev()
            .map(|line| {
                let age = now.duration_since(line.at).as_secs_f32();
                let alpha = if age <= 10.0 {
                    1.0
                } else {
                    (1.0 - (age - 10.0) / 4.0).clamp(0.0, 1.0)
                };
                (line.text.clone(), alpha)
            })
            .collect();
        let input = self.chat_open.then_some(self.chat_input.as_str());
        ui::draw_chat(
            &mut self.ui_bg,
            &mut self.ui_fg,
            &lines,
            input,
            scale,
            width,
            height,
        );
    }

    /// Select a row. A second click on the same row within [`DOUBLE_CLICK`]
    /// joins it â€” 1.8's gesture, and the reason a single click must not join.
    fn select_server(&mut self, index: usize) {
        let Some(entry) = self.servers.entries().get(index) else {
            return;
        };
        let address = entry.address.clone();
        let now = Instant::now();
        let double = self
            .last_server_click
            .as_ref()
            .is_some_and(|(at, previous)| {
                previous == &address && now.duration_since(*at) < DOUBLE_CLICK
            });
        self.last_server_click = Some((now, address.clone()));
        self.servers_selected = Some(address);
        if double {
            self.join_server(index);
        }
    }

    /// Join whatever `Join Server` / Enter would join.
    fn join_selected_server(&mut self) {
        let Some(selected) = self.servers_selected.clone() else {
            return;
        };
        let Some(index) = self
            .servers
            .entries()
            .iter()
            .position(|entry| entry.address == selected)
        else {
            return;
        };
        self.join_server(index);
    }

    fn save_servers(&self) {
        if let Err(err) = self.servers.save(&self.options.servers_path) {
            eprintln!("could not save the server list: {err}");
        }
    }

    /// Join a saved server by its storage index.
    fn join_server(&mut self, index: usize) {
        let Some(entry) = self.servers.entries().get(index) else {
            return;
        };
        let address = entry.address.clone();
        match ServerAddress::parse(&address) {
            Ok(address) => self.start_network(address),
            Err(err) => {
                self.shared.lock().unwrap().status = format!("bad address: {err}");
            }
        }
    }

    /// Number of entries the list can scroll past the last visible row.
    fn servers_max_scroll(&self) -> usize {
        self.servers.entries().len().saturating_sub(ui::SERVER_ROWS)
    }

    /// Move the saved-server list, clamped to the entries it has.
    fn scroll_servers(&mut self, steps: i32) {
        let next = self.servers_scroll as i32 - steps;
        self.servers_scroll = next.clamp(0, self.servers_max_scroll() as i32) as usize;
    }

    /// Push settings that live outside the UI into the renderer and network.
    fn apply_settings(&mut self) {
        if let Some(renderer) = self.renderer.as_mut() {
            renderer.set_vsync(self.settings.vsync);
        }
        if let Some(audio) = &self.audio {
            audio.set_master_volume(self.settings.volume);
        }
        let mut shared = self.shared.lock().unwrap();
        shared.view_distance = self.settings.view_distance;
    }

    fn open_pause(&mut self) {
        self.screen = Screen::Pause;
        self.set_mouse_capture(false);
    }

    fn open_creative(&mut self) {
        self.screen = Screen::Creative;
        self.set_mouse_capture(false);
        self.creative_page = 0;
    }

    fn open_inventory(&mut self) {
        self.screen = Screen::Inventory;
        self.set_mouse_capture(false);
        self.inventory_cursor = None;
    }

    /// Close the inventory, putting whatever is on the cursor back first.
    fn close_inventory(&mut self) {
        let mut state = self.shared.lock().unwrap();
        if state.window_open {
            if state.local && state.window_id == Some(1) {
                // A local crafting table has no server to return its grid. Make
                // the close atomic so a full inventory never destroys items.
                let mut inventory = state.inventory.clone();
                if let Some(cursor) = state.local_container.cursor() {
                    if insert_player_stack(&mut inventory, cursor).is_some() {
                        return;
                    }
                }
                for item in state.local_container.grid().iter().flatten() {
                    if insert_player_stack(&mut inventory, *item).is_some() {
                        return;
                    }
                }
                state.inventory = inventory;
                state.local_container = LocalContainer::default();
                state.window_slots.clear();
                state.window_open = false;
                state.window_id = None;
                state.close_window = false;
                self.inventory_cursor = None;
                refresh_local_crafting_preview(&mut state);
                drop(state);
                self.enter_game();
                return;
            }
            // The server returns the grid and cursor stacks when it closes.
            self.inventory_cursor = None;
            state.close_window = true;
            drop(state);
            self.enter_game();
            return;
        }

        if state.local {
            let mut inventory = state.inventory.clone();
            if let Some(cursor) = self.inventory_cursor {
                if inventory::insert_stack(&mut inventory[9..45], cursor).is_some() {
                    return;
                }
            }
            state.inventory = inventory;
            self.inventory_cursor = None;
            drop(state);
            self.enter_game();
            return;
        }

        if self.inventory_cursor.is_some() {
            let free = (play::HOTBAR_FIRST_SLOT..state.inventory.len())
                .chain(9..play::HOTBAR_FIRST_SLOT)
                .find(|&slot| state.inventory[slot].is_none());
            let Some(slot) = free else {
                return;
            };
            drop(state);
            self.inventory_click(slot as i16, 0, false);
        } else {
            drop(state);
        }
        self.enter_game();
    }

    /// Resolve one click in the inventory screen.
    ///
    /// The cursor lives here, the slots live on the server (single-player keeps
    /// them locally). `clicked` is our copy of the slot *before* the click, which
    /// the server checks for staleness.
    fn inventory_click(&mut self, slot: i16, button: i8, shift: bool) {
        let mut state = self.shared.lock().unwrap();
        let Ok(index) = usize::try_from(slot) else {
            return;
        };
        // An open container replaces the player container: slot numbers are the
        // window's (0 = output, 1..9 = grid, 10.. = storage/hotbar).
        let open = state.window_open;
        let local_table = state.local && state.window_id == Some(1);
        let count = if open {
            state.window_slots.len()
        } else {
            state.inventory.len()
        };
        if index >= count {
            return;
        }

        let clicked = if open {
            state.window_slots.get(index).copied().flatten()
        } else {
            state.inventory[index]
        };

        if state.local {
            if local_table {
                if shift {
                    if index == 0 {
                        shift_craft_local_outputs(&mut state);
                    } else if (1..10).contains(&index) {
                        let mut container = state.local_container.clone();
                        let Some(item) = container.click(index, button, true) else {
                            return;
                        };
                        let mut inventory = state.inventory.clone();
                        let remainder = insert_player_stack(&mut inventory, item);
                        container.set_grid_cell(index - 1, remainder);
                        state.local_container = container;
                        state.inventory = inventory;
                        refresh_local_crafting_preview(&mut state);
                    } else {
                        inventory::quick_move(&mut state.inventory, index - 1);
                        refresh_local_crafting_preview(&mut state);
                    }
                    return;
                }

                if index < 10 {
                    state.local_container.click(index, button, false);
                } else {
                    let inventory_slot = index - 1;
                    let (cursor, new_slot) = inventory::click(
                        state.local_container.cursor(),
                        state.inventory[inventory_slot],
                        button,
                    );
                    state.local_container.set_cursor(cursor);
                    state.inventory[inventory_slot] = new_slot;
                }
                refresh_local_crafting_preview(&mut state);
                return;
            }

            if shift {
                if index == 0 {
                    shift_craft_local_outputs(&mut state);
                } else {
                    inventory::quick_move(&mut state.inventory, index);
                    refresh_local_crafting_preview(&mut state);
                }
                return;
            }

            if index == 0 {
                take_local_crafting_output(&mut state, &mut self.inventory_cursor);
                return;
            }

            let (cursor, new_slot) = inventory::click(self.inventory_cursor, clicked, button);
            self.inventory_cursor = cursor;
            state.inventory[index] = new_slot;
            refresh_local_crafting_preview(&mut state);
            return;
        }

        if shift {
            state
                .inventory_clicks
                .push((slot, 0, play::click_mode::SHIFT_CLICK, clicked));
            return;
        }

        let (cursor, _) = inventory::click(self.inventory_cursor, clicked, button);
        self.inventory_cursor = cursor;
        state
            .inventory_clicks
            .push((slot, button, play::click_mode::CLICK, clicked));
    }

    fn enter_game(&mut self) {
        self.screen = Screen::Game;
        self.set_mouse_capture(true);
    }

    fn handle_action(&mut self, action: Action, event_loop: &ActiveEventLoop) {
        match action {
            Action::Singleplayer => self.open_worlds(),
            Action::Multiplayer => self.open_servers(),
            Action::WorldOpen(index) => self.open_saved_world(index),
            Action::WorldNew => self.open_world_create(),
            Action::WorldsBack => {
                self.world_error = None;
                self.screen = Screen::Title;
            }
            Action::WorldNameFocus => {
                self.world_name_focused = true;
                self.world_seed_focused = false;
                self.world_error = None;
            }
            Action::WorldSeedFocus => {
                self.world_name_focused = false;
                self.world_seed_focused = true;
                self.world_error = None;
            }
            Action::WorldModeToggle => {
                self.world_create_mode = match self.world_create_mode {
                    WorldMode::Creative => WorldMode::Survival,
                    WorldMode::Survival => WorldMode::Creative,
                };
                self.world_error = None;
            }
            Action::WorldCreateSubmit => self.create_local_world(),
            Action::WorldCreateCancel => {
                self.world_error = None;
                self.screen = Screen::Worlds;
            }
            Action::ServersJoin => self.join_selected_server(),
            Action::ServersDirectConnect => {
                self.address_input.clear();
                self.screen = Screen::Connect;
            }
            Action::ServersRefresh => self.refresh_server_list(),
            Action::ServersBack => self.screen = Screen::Title,
            Action::ServerSelect(index) => self.select_server(index),
            Action::ServerFavourite(index) => {
                self.servers.toggle_favourite(index);
                self.save_servers();
            }
            Action::ServerRemove(index) => {
                let removed = self
                    .servers
                    .entries()
                    .get(index)
                    .map(|entry| entry.address.clone());
                self.servers.remove(index);
                if removed == self.servers_selected {
                    self.servers_selected = None;
                }
                self.save_servers();
                self.servers_scroll = self.servers_scroll.min(self.servers_max_scroll());
            }
            Action::TitleOptions => {
                self.settings_return = Screen::Title;
                self.screen = Screen::Settings;
            }
            Action::Quit => event_loop.exit(),
            Action::ConnectSubmit => self.connect_from_input(),
            Action::ConnectCancel => self.screen = Screen::Servers,
            Action::Resume => self.enter_game(),
            Action::OpenSettings => {
                self.settings_return = Screen::Pause;
                self.screen = Screen::Settings;
            }
            Action::SettingsDone => self.screen = self.settings_return,
            Action::SettingAdjust(id, delta) => {
                if self.settings.adjust(id, delta) {
                    self.apply_settings();
                }
            }
            Action::Disconnect => event_loop.exit(),
            Action::Respawn => {
                let mut shared = self.shared.lock().unwrap();
                shared.pending_respawn = true;
                // The server picks the real value; clearing the stale zero stops
                // the death screen reappearing before the respawn packet lands.
                shared.health = 20.0;
                drop(shared);
                self.screen = Screen::Game;
            }
            Action::CreativePage(delta) => {
                let pages = ui::creative_pages().max(1);
                let next = self.creative_page as i32 + delta;
                self.creative_page = next.clamp(0, pages as i32 - 1) as usize;
            }
            Action::CreativeItem(index) => {
                let Some(state) = ui::creative_items().get(index).copied() else {
                    return;
                };
                let item = ItemStack::new(state.id() as i16, 64, state.meta() as i16);
                let mut shared = self.shared.lock().unwrap();
                let slot = play::HOTBAR_FIRST_SLOT + shared.held_slot.max(0) as usize;
                shared.give_item = Some((slot as i16, item));
            }
            Action::SelectSlot(slot) => {
                let mut shared = self.shared.lock().unwrap();
                shared.pending_slot = Some(slot as i16);
            }
            // Container clicks need the mouse button, so the inventory screen
            // handles them directly instead of going through this action list.
            Action::InventorySlot(_) => {}
        }
    }
}

impl ApplicationHandler for LiveApp {
    /// Raw mouse motion is the only source of look deltas while the cursor is
    /// locked: Windows pins the absolute position, so CursorMoved reports
    /// the same coordinates forever.
    fn device_event(
        &mut self,
        _event_loop: &ActiveEventLoop,
        _device_id: DeviceId,
        event: DeviceEvent,
    ) {
        if let DeviceEvent::MouseMotion { delta } = event {
            if self.mouse_captured && self.screen == Screen::Game {
                self.raw_motion = true;
                self.look(delta.0 as f32, delta.1 as f32);
            }
        }
    }

    fn resumed(&mut self, event_loop: &ActiveEventLoop) {
        if self.window.is_none() {
            self.init(event_loop);
        }
    }

    fn window_event(&mut self, event_loop: &ActiveEventLoop, _id: WindowId, event: WindowEvent) {
        match event {
            WindowEvent::CloseRequested => event_loop.exit(),
            WindowEvent::ModifiersChanged(modifiers) => {
                self.shift = modifiers.state().shift_key();
            }
            WindowEvent::Resized(size) => {
                if let Some(renderer) = self.renderer.as_mut() {
                    renderer.resize(size.width, size.height);
                }
            }
            // Multiplayer doesn't pause when the window loses focus (only
            // singleplayer does); just let go of the mouse.
            WindowEvent::Focused(true) => {
                self.focus_gained = Some(Instant::now());
            }
            WindowEvent::Focused(false) => {
                self.keys.clear();
                if self.mouse_captured {
                    self.set_mouse_capture(false);
                }
            }
            WindowEvent::KeyboardInput { event, .. } => {
                // While the chat line is open it owns the keyboard.
                if self.chat_open && event.state == ElementState::Pressed {
                    match event.physical_key {
                        PhysicalKey::Code(KeyCode::Enter) => {
                            self.send_chat_line();
                            return;
                        }
                        PhysicalKey::Code(KeyCode::Escape) => {
                            self.chat_open = false;
                            self.chat_input.clear();
                            self.enter_game();
                            return;
                        }
                        PhysicalKey::Code(KeyCode::Backspace) => {
                            self.chat_input.pop();
                            return;
                        }
                        _ => {}
                    }
                    if let Some(text) = event.text.as_ref() {
                        for ch in text.chars() {
                            if !ch.is_control() && self.chat_input.len() < 256 {
                                self.chat_input.push(ch);
                            }
                        }
                    }
                    return;
                }
                if self.screen == Screen::WorldCreate && event.state == ElementState::Pressed {
                    match event.physical_key {
                        PhysicalKey::Code(KeyCode::Enter) => {
                            self.create_local_world();
                            return;
                        }
                        PhysicalKey::Code(KeyCode::Escape) => {
                            self.screen = Screen::Worlds;
                            self.world_error = None;
                            return;
                        }
                        PhysicalKey::Code(KeyCode::Backspace) => {
                            if self.world_name_focused {
                                self.world_name_input.pop();
                            } else if self.world_seed_focused {
                                self.world_seed_input.pop();
                            }
                            return;
                        }
                        _ => {}
                    }
                    if let Some(text) = event.text.as_ref() {
                        for ch in text.chars() {
                            if ch.is_control() {
                                continue;
                            }
                            if self.world_name_focused && self.world_name_input.chars().count() < 64
                            {
                                self.world_name_input.push(ch);
                            } else if self.world_seed_focused
                                && ch.is_ascii_digit()
                                && self.world_seed_input.len() < 20
                            {
                                self.world_seed_input.push(ch);
                            }
                        }
                    }
                    return;
                }
                // The direct-connect screen is a text field.
                if self.screen == Screen::Connect && event.state == ElementState::Pressed {
                    match event.physical_key {
                        PhysicalKey::Code(KeyCode::Enter) => {
                            self.connect_from_input();
                            return;
                        }
                        PhysicalKey::Code(KeyCode::Escape) => {
                            self.screen = Screen::Servers;
                            return;
                        }
                        PhysicalKey::Code(KeyCode::Backspace) => {
                            self.address_input.pop();
                            return;
                        }
                        _ => {}
                    }
                    if let Some(text) = event.text.as_ref() {
                        for ch in text.chars() {
                            if !ch.is_control() && self.address_input.len() < 64 {
                                self.address_input.push(ch);
                            }
                        }
                    }
                    return;
                }
                // Enter joins the selected server; letters do nothing here, the
                // list has no text field of its own.
                if self.screen == Screen::Servers
                    && event.state == ElementState::Pressed
                    && event.physical_key == PhysicalKey::Code(KeyCode::Enter)
                {
                    self.join_selected_server();
                    return;
                }
                if let PhysicalKey::Code(code) = event.physical_key {
                    match (code, event.state) {
                        (KeyCode::Escape, ElementState::Pressed) => match self.screen {
                            Screen::Game => self.open_pause(),
                            Screen::Pause | Screen::Creative => self.enter_game(),
                            Screen::Inventory => self.close_inventory(),
                            Screen::Settings => self.screen = self.settings_return,
                            Screen::Title => {}
                            Screen::Worlds | Screen::Servers => self.screen = Screen::Title,
                            Screen::WorldCreate => {
                                self.screen = Screen::Worlds;
                                self.world_error = None;
                            }
                            Screen::Connect | Screen::Death => self.screen = Screen::Title,
                        },
                        (KeyCode::KeyT, ElementState::Pressed) if self.screen == Screen::Game => {
                            self.open_chat(false);
                        }
                        (KeyCode::Slash, ElementState::Pressed) if self.screen == Screen::Game => {
                            self.open_chat(true);
                        }
                        (KeyCode::KeyE, ElementState::Pressed) => match self.screen {
                            Screen::Game => {
                                let creative = self.shared.lock().unwrap().creative;
                                if creative {
                                    self.open_creative();
                                } else {
                                    self.open_inventory();
                                }
                            }
                            Screen::Creative => self.enter_game(),
                            Screen::Inventory => self.close_inventory(),
                            Screen::Pause
                            | Screen::Settings
                            | Screen::Title
                            | Screen::Worlds
                            | Screen::WorldCreate
                            | Screen::Servers
                            | Screen::Connect
                            | Screen::Death => {}
                        },
                        (KeyCode::KeyF, ElementState::Pressed) if self.screen == Screen::Game => {
                            let mut state = self.shared.lock().unwrap();
                            state.player.flying = !state.player.flying;
                            state.player.vy = 0.0;
                            println!("flying: {}", state.player.flying);
                        }
                        (digit, ElementState::Pressed) if self.screen == Screen::Game => {
                            if let Some(slot) = hotbar_digit(digit) {
                                let mut state = self.shared.lock().unwrap();
                                state.pending_slot = Some(slot);
                            } else {
                                self.keys.insert(code);
                            }
                        }
                        (_, ElementState::Released) => {
                            self.keys.remove(&code);
                        }
                        _ => {}
                    }
                }
            }
            WindowEvent::MouseInput { state, button, .. } => {
                // Menus use the free cursor; the game uses the captured one.
                if self.screen == Screen::Inventory {
                    if state == ElementState::Pressed {
                        if let Some([x, y]) = self.pointer {
                            if let Some(ui::Action::InventorySlot(slot)) =
                                ui::hit_test(&self.buttons, [x, y])
                            {
                                let button = if button == MouseButton::Right { 1 } else { 0 };
                                self.inventory_click(slot as i16, button, self.shift);
                            }
                        }
                    }
                    return;
                }
                if self.screen != Screen::Game {
                    if button == MouseButton::Left && state == ElementState::Pressed {
                        if let Some([x, y]) = self.pointer {
                            if let Some(action) = ui::hit_test(&self.buttons, [x, y]) {
                                self.handle_action(action, event_loop);
                            }
                        }
                    }
                    return;
                }
                if !self.mouse_captured {
                    if state == ElementState::Pressed {
                        self.set_mouse_capture(true);
                    }
                    return;
                }
                match (button, state) {
                    (MouseButton::Left, ElementState::Pressed) => {
                        let mut shared = self.shared.lock().unwrap();
                        shared.attacking = true;
                    }
                    (MouseButton::Left, ElementState::Released) => {
                        let mut shared = self.shared.lock().unwrap();
                        shared.attacking = false;
                    }
                    (MouseButton::Right, ElementState::Pressed) => {
                        let mut shared = self.shared.lock().unwrap();
                        shared.use_pressed = true;
                    }
                    _ => {}
                }
            }
            WindowEvent::MouseWheel { delta, .. } if self.screen == Screen::Servers => {
                let steps = match delta {
                    MouseScrollDelta::LineDelta(_, y) => y.round() as i32,
                    MouseScrollDelta::PixelDelta(position) => (position.y / 40.0).round() as i32,
                };
                if steps != 0 {
                    self.scroll_servers(steps);
                }
            }
            WindowEvent::MouseWheel { delta, .. } if self.screen == Screen::Worlds => {
                let steps = match delta {
                    MouseScrollDelta::LineDelta(_, y) => y.round() as i32,
                    MouseScrollDelta::PixelDelta(position) => (position.y / 40.0).round() as i32,
                };
                if steps != 0 {
                    self.scroll_worlds(steps);
                }
            }
            WindowEvent::MouseWheel { delta, .. } if self.screen == Screen::Game => {
                let steps = match delta {
                    MouseScrollDelta::LineDelta(_, y) => y.round() as i16,
                    MouseScrollDelta::PixelDelta(position) => (position.y / 40.0).round() as i16,
                };
                if steps != 0 {
                    let mut state = self.shared.lock().unwrap();
                    let slot = (state.held_slot - steps).rem_euclid(9);
                    state.pending_slot = Some(slot);
                }
            }
            WindowEvent::CursorMoved { position, .. } => {
                if !self.mouse_captured {
                    self.pointer = Some([position.x as f32, position.y as f32]);
                } else {
                    // With a locked cursor the absolute position is pinned, so
                    // these deltas are only a fallback for platforms that don't
                    // send raw motion (see `device_event`).
                    if !self.raw_motion {
                        if let Some(last) = self.last_cursor {
                            self.look((position.x - last.x) as f32, (position.y - last.y) as f32);
                        }
                    }
                    self.last_cursor = Some(position);
                }
            }
            WindowEvent::RedrawRequested => {
                self.frame();
                if let Some(window) = self.window.as_ref() {
                    window.request_redraw();
                }
            }
            _ => {}
        }
    }
}

/// Settings for this run. `NEPHELE_VIEW_DISTANCE` overrides the render
/// distance so the far view can be exercised without clicking through Options.
fn initial_settings() -> Settings {
    settings_with_view_distance_override(
        Settings::default(),
        std::env::var("NEPHELE_VIEW_DISTANCE").ok().as_deref(),
    )
}

fn settings_with_view_distance_override(mut settings: Settings, value: Option<&str>) -> Settings {
    if let Some(value) = value {
        if let Ok(distance) = value.trim().parse::<u8>() {
            settings.view_distance = distance.clamp(2, 16);
        }
    }
    settings
}

/// The configured render distance before the first local world starts.
fn configured_view_distance(settings: &Settings) -> u8 {
    settings.view_distance
}

/// The chunk radius the local streaming loop uses for the shared state.
fn local_stream_radius(state: &Shared) -> i32 {
    view_radius(state.view_distance)
}

/// Chunk radius to generate around the player for a given render distance.
fn view_radius(view_distance: u8) -> i32 {
    i32::from(view_distance).clamp(2, 16)
}

/// Ping one server for the multiplayer screen. Runs on its own thread â€” this
/// blocks for up to [`PING_TIMEOUT`] and must never touch the render thread.
fn ping_server(address: &str) -> Ping {
    let Ok(parsed) = ServerAddress::parse(address) else {
        return Ping::Offline;
    };
    let runtime = match tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()
    {
        Ok(runtime) => runtime,
        Err(err) => {
            eprintln!("could not start the ping runtime: {err}");
            return Ping::Offline;
        }
    };
    match runtime.block_on(nephele_protocol::ping(&parsed, PING_TIMEOUT)) {
        Ok(status) => Ping::Online(Status {
            motd: crate::strip_formatting(&status.description),
            version: status.version_name.unwrap_or_else(|| "?".to_string()),
            ping_ms: status.latency.map(|d| d.as_millis() as u32).unwrap_or(0),
        }),
        Err(_) => Ping::Offline,
    }
}

/// Interpolate between two Minecraft angles the short way round.
fn lerp_degrees(previous: f32, current: f32, alpha: f64) -> f32 {
    let mut delta = (current - previous) % 360.0;
    if delta >= 180.0 {
        delta -= 360.0;
    }
    if delta < -180.0 {
        delta += 360.0;
    }
    (previous + delta * alpha.clamp(0.0, 1.0) as f32).rem_euclid(360.0)
}

/// Flat colour for a mob, so unspecified mobs are at least distinguishable.
/// Armour material tint by item id. The exact layer textures are not loaded
/// yet, so a solid tinted shell is used; the silhouette and slot are correct.
fn armor_tint(item: i16) -> Option<[f32; 4]> {
    let color = match item {
        298..=301 => [0.55, 0.36, 0.22, 0.6], // leather
        302..=305 => [0.62, 0.62, 0.62, 0.6], // chain
        306..=309 => [0.55, 0.55, 0.58, 0.6], // iron
        310..=313 => [0.32, 0.78, 0.78, 0.6], // diamond
        314..=317 => [0.95, 0.80, 0.25, 0.6], // gold
        _ => return None,
    };
    Some(color)
}

/// In 1.8 a filled map's damage value is its map id.
fn map_id_of(item: &ItemStack) -> Option<i32> {
    (item.id == play::ITEM_FILLED_MAP).then_some(item.damage as i32)
}

/// A flat colour for a framed non-map item. Maps use their real pixels; this
/// keeps a framed sword or block from rendering as an invisible quad.
fn frame_item_tint(item: i16) -> [f32; 4] {
    if let Some(color) = armor_tint(item) {
        return color;
    }
    let hash = item.unsigned_abs() as u32;
    [
        0.35 + (hash % 7) as f32 * 0.08,
        0.35 + ((hash / 7) % 7) as f32 * 0.08,
        0.35 + ((hash / 49) % 7) as f32 * 0.08,
        1.0,
    ]
}

fn mob_tint(kind: u8) -> [f32; 4] {
    match kind {
        // Zombie / skeleton / creeper / spider / pig.
        54 => [0.45, 0.62, 0.36, 1.0],
        51 => [0.88, 0.88, 0.85, 1.0],
        50 => [0.42, 0.75, 0.36, 1.0],
        52 => [0.25, 0.22, 0.20, 1.0],
        90 => [0.95, 0.60, 0.62, 1.0],
        _ => [0.80, 0.55, 0.70, 1.0],
    }
}

fn mob_scale(kind: u8) -> f32 {
    match kind {
        50 | 52 | 59 => 0.9,
        55 | 62 => 0.8,
        65 => 0.5,
        90..=92 | 95 | 96 => 0.9,
        93 => 0.6,
        94 => 0.9,
        _ => 1.0,
    }
}

/// The 16 vanilla banner base colours, as render tints.
fn banner_tint(base: u8) -> [f32; 4] {
    const COLORS: [[f32; 3]; 16] = [
        [1.0, 1.0, 1.0],    // white
        [0.85, 0.45, 0.20], // orange
        [0.65, 0.35, 0.85], // magenta
        [0.40, 0.65, 0.90], // light blue
        [0.95, 0.85, 0.25], // yellow
        [0.35, 0.75, 0.30], // lime
        [0.90, 0.55, 0.65], // pink
        [0.35, 0.35, 0.35], // gray
        [0.60, 0.60, 0.60], // silver
        [0.25, 0.55, 0.60], // cyan
        [0.45, 0.25, 0.65], // purple
        [0.20, 0.30, 0.65], // blue
        [0.40, 0.30, 0.20], // brown
        [0.25, 0.40, 0.25], // green
        [0.65, 0.25, 0.25], // red
        [0.15, 0.15, 0.15], // black
    ];
    let color = COLORS[base as usize % COLORS.len()];
    [color[0], color[1], color[2], 1.0]
}

/// `1`..`9` selects hotbar slots 0..8, exactly like vanilla.
/// Would a full block at these coordinates overlap the player's bounding box?
fn block_hits_player(x: i32, y: i32, z: i32, feet: [f64; 3]) -> bool {
    let x = x as f64;
    let y = y as f64;
    let z = z as f64;
    let half = nephele_client::physics::WIDTH / 2.0;
    let height = nephele_client::physics::HEIGHT;

    x < feet[0] + half
        && x + 1.0 > feet[0] - half
        && y < feet[1] + height
        && y + 1.0 > feet[1]
        && z < feet[2] + half
        && z + 1.0 > feet[2] - half
}

/// Door placement must keep both its lower and upper cells clear of the player.
fn door_placement_hits_player(x: i32, y: i32, z: i32, feet: [f64; 3]) -> bool {
    block_hits_player(x, y, z, feet) || block_hits_player(x, y + 1, z, feet)
}

/// Would placing the block at `aim`'s face put it inside the player?
///
/// Vanilla refuses such a placement outright (`World.checkNoEntityCollision`),
/// which is why placing under your own feet does nothing instead of shoving you
/// upward.
fn placement_hits_player(aim: &Aim, feet: [f64; 3]) -> bool {
    let normal = nephele_world::Face::from_protocol_id(aim.face)
        .map(|face| face.normal())
        .unwrap_or([0, 1, 0]);
    block_hits_player(
        aim.x + normal[0],
        aim.y + normal[1],
        aim.z + normal[2],
        feet,
    )
}

fn hotbar_digit(code: KeyCode) -> Option<i16> {
    let slot = match code {
        KeyCode::Digit1 => 0,
        KeyCode::Digit2 => 1,
        KeyCode::Digit3 => 2,
        KeyCode::Digit4 => 3,
        KeyCode::Digit5 => 4,
        KeyCode::Digit6 => 5,
        KeyCode::Digit7 => 6,
        KeyCode::Digit8 => 7,
        KeyCode::Digit9 => 8,
        _ => return None,
    };
    Some(slot)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn local_state_for_test() -> Shared {
        Shared {
            player: PlayerState::default(),
            yaw: 0.0,
            pitch: 0.0,
            input: Input::default(),
            teleport: None,
            status: String::new(),
            spawned: false,
            error: None,
            attacking: false,
            use_pressed: false,
            pending_slot: None,
            pending_respawn: false,
            aim: None,
            break_stage: None,
            held_slot: 0,
            creative: false,
            inventory: vec![None; 45],
            health: 20.0,
            food: 20,
            xp_bar: 0.0,
            xp_level: 0,
            chunks: 0,
            give_item: None,
            chat_out: Vec::new(),
            world_edits: Vec::new(),
            creative_override: None,
            inventory_clicks: Vec::new(),
            window_slots: Vec::new(),
            window_open: false,
            window_id: None,
            local_container: LocalContainer::default(),
            close_window: false,
            local: true,
            view_distance: nephele_client::VIEW_DISTANCE,
            time_of_day: 6000,
            time_override: None,
            prev_position: [0.5, 64.0, 0.5],
            tick_at: Instant::now(),
        }
    }

    #[test]
    fn local_crafting_table_opens_window_one_and_projects_its_slots() {
        let mut state = local_state_for_test();
        state.inventory[9] = Some(ItemStack::new(17, 2, 0));
        open_local_crafting_table(&mut state);

        assert_eq!(state.window_id, Some(1));
        assert!(state.window_open);
        assert_eq!(state.window_slots.len(), 46);
        assert_eq!(state.window_slots[10], state.inventory[9]);

        state
            .local_container
            .set_grid_cell(0, Some(ItemStack::new(17, 1, 0)));
        refresh_local_crafting_preview(&mut state);
        assert_eq!(state.window_slots[0], Some(ItemStack::new(5, 4, 0)));
        assert_eq!(state.window_slots[1], Some(ItemStack::new(17, 1, 0)));
    }

    #[test]
    fn local_shift_crafting_preserves_ingredients_until_the_output_fits() {
        let mut state = local_state_for_test();
        state.inventory.fill(Some(ItemStack::new(1, 64, 0)));
        open_local_crafting_table(&mut state);
        state
            .local_container
            .set_grid_cell(0, Some(ItemStack::new(17, 2, 0)));
        refresh_local_crafting_preview(&mut state);

        shift_craft_local_outputs(&mut state);
        assert_eq!(state.inventory[36], Some(ItemStack::new(1, 64, 0)));
        assert_eq!(
            state.local_container.grid()[0],
            Some(ItemStack::new(17, 2, 0))
        );

        state.inventory[36] = None;
        shift_craft_local_outputs(&mut state);
        assert_eq!(state.inventory[36], Some(ItemStack::new(5, 8, 0)));
        assert_eq!(state.local_container.grid()[0], None);
        assert_eq!(state.window_slots[0], None);
    }

    #[test]
    fn nephele_view_distance_override_reaches_the_local_streaming_radius() {
        let settings = settings_with_view_distance_override(Settings::default(), Some("6"));
        let mut state = local_state_for_test();
        state.view_distance = configured_view_distance(&settings);

        assert_eq!(local_stream_radius(&state), 6);

        let settings = settings_with_view_distance_override(Settings::default(), Some("11"));
        state.view_distance = configured_view_distance(&settings);
        assert_eq!(local_stream_radius(&state), 11);
    }

    #[test]
    fn hotbar_digits_map_to_slots() {
        assert_eq!(hotbar_digit(KeyCode::Digit1), Some(0));
        assert_eq!(hotbar_digit(KeyCode::Digit9), Some(8));
        assert_eq!(hotbar_digit(KeyCode::KeyW), None);
    }

    /// A player standing on the block at (0, 63, 0), so their feet are at y = 64.
    fn standing_on_a_block() -> [f64; 3] {
        [0.5, 64.0, 0.5]
    }

    fn hit(aim: Aim) -> bool {
        placement_hits_player(&aim, standing_on_a_block())
    }

    #[test]
    fn placing_on_the_block_below_your_feet_is_refused() {
        // Top face of the block you are standing on: the new block would
        // occupy the space your legs are in.
        let aim = Aim {
            x: 0,
            y: 63,
            z: 0,
            face: 1,
            cursor: [0.5, 1.0, 0.5],
        };
        assert!(hit(aim));
    }

    #[test]
    fn placing_beside_or_above_you_is_allowed() {
        // East face of a block far to the side.
        let beside = Aim {
            x: 4,
            y: 63,
            z: 0,
            face: 5,
            cursor: [1.0, 0.5, 0.5],
        };
        assert!(!hit(beside));

        // Top face of a block two above the feet: clear of the head.
        let above = Aim {
            x: 0,
            y: 65,
            z: 0,
            face: 1,
            cursor: [0.5, 1.0, 0.5],
        };
        assert!(!hit(above));
    }

    #[test]
    fn door_placement_checks_the_upper_half_against_the_player() {
        let feet = standing_on_a_block();
        assert!(!block_hits_player(0, 63, 0, feet));
        assert!(door_placement_hits_player(0, 63, 0, feet));
        assert!(!door_placement_hits_player(0, 66, 0, feet));
    }

    #[test]
    fn placing_into_your_own_head_space_is_refused() {
        // The block at head height, reached from the side.
        let aim = Aim {
            x: 0,
            y: 63,
            z: 0,
            face: 1,
            cursor: [0.5, 1.0, 0.5],
        };
        assert!(hit(aim));

        // One block up still overlaps the head, which reaches 65.8.
        let head = Aim { y: 64, ..aim };
        assert!(hit(head));

        // One higher clears it.
        let clear = Aim { y: 65, ..aim };
        assert!(!hit(clear));
    }

    #[test]
    fn look_direction_matches_the_camera() {
        let forward = look_direction(0.0, 0.0);
        assert!(forward[0].abs() < 1e-6);
        assert!(forward[1].abs() < 1e-6);
        assert!((forward[2] + 1.0).abs() < 1e-6);

        let up = look_direction(0.0, std::f32::consts::FRAC_PI_2);
        assert!((up[1] - 1.0).abs() < 1e-6);
    }

    #[test]
    fn night_starts_at_dusk_and_darkens_the_world() {
        assert!(!is_night(12_999));
        assert!(is_night(15_000));
        assert!(is_night(22_999));
        assert!(!is_night(23_000));
        assert!((world_light(15_000) - 0.28).abs() < 1e-6);
        assert!(world_light(6_000) > 0.9);
        assert!(sky_color(15_000)[0] < sky_color(6_000)[0]);
    }

    #[test]
    fn local_survival_drops_logs_without_their_axis_bits() {
        assert_eq!(
            local_block_drop(BlockState::new(17, 0b1010)),
            Some(ItemStack::new(17, 1, 2))
        );
        assert_eq!(
            local_block_drop(BlockState::STONE),
            Some(ItemStack::new(4, 1, 0))
        );
        assert_eq!(local_block_drop(BlockState::BEDROCK), None);
    }
}
